def _safe_ratio(numerator: float, denominator: float) -> float:
    if denominator <= 0:
        return 0.0
    return float(numerator) / float(denominator)


def _clip01(value: float) -> float:
    if value <= 0.0:
        return 0.0
    if value >= 1.0:
        return 1.0
    return float(value)


def _normalized_available_actions_from_observation(
    observation: dict[str, Any] | None,
    *,
    state: ECAState | None = None,
) -> list[str]:
    raw_available = []
    if isinstance(observation, dict):
        raw_available = list(observation.get("available_actions") or [])
    allowed: list[str] = []
    seen: set[str] = set()
    for action_id in raw_available:
        raw_action = str(action_id or "").strip().upper()
        action_name = ""
        if raw_action.startswith("ACTION") and raw_action[6:].isdigit():
            action_name = raw_action
        elif raw_action.isdigit():
            action_name = f"ACTION{int(raw_action)}"
        if action_name and action_name not in seen:
            seen.add(action_name)
            allowed.append(action_name)
    move_present = any(action in {"ACTION1", "ACTION2", "ACTION3", "ACTION4"} for action in allowed)
    click_missing = "ACTION6" not in seen
    object_table = list(getattr(state, "object_table", None) or []) if state is not None else []
    if move_present and click_missing and object_table:
        allowed.append("ACTION6")
    return allowed


