    def __init__(
        self,
        *,
        game_id: str | None,
        max_actions: int,
        config: ECAConfig | dict[str, Any] | None = None,
        output_dir: Path | None = None,
        run_id: str | None = None,
    ) -> None:
        _raw_config_dict: dict[str, Any] | None = config if isinstance(config, dict) else None
        self.config = config if isinstance(config, ECAConfig) else ECAConfig.from_mapping(config)
        # Preserve experimental v2 sections from raw dict.
        # ECAConfig.from_mapping does not include these fields yet.
        if _raw_config_dict is not None:
            for _section in ("control_ir", "local_controller", "target_health", "candidate_extractor"):
                if _section in _raw_config_dict and not hasattr(self.config, _section):
                    setattr(self.config, _section, _raw_config_dict[_section])
        self.game_id = game_id
        self.max_actions = max_actions
        self.output_dir = output_dir
        self.run_id = run_id or f"{game_id or 'game'}:run"
        self.rng = random.Random(self.config.random_seed)

        self.analyzer_calls = 0
        self.replan_requests = 0
        self.interrupt_count = 0
        self.level_interrupt_count = 0
        self.soft_interrupt_count = 0
        self.queue_exhaustions = 0
        self.score_change_flushes = 0
        self.queue_waste_actions = 0
        self.queued_actions_total = 0
        self.plan_generation = 0
        self.plan_start_total = 0.0
        self.plan_start_interrupt_total = 0.0
        self.plan_start_top_drive = "bootstrap"
        self.last_interrupt_step = -10_000
        self.last_level_number = 1
        self.last_snapshot: AnxietySnapshot | None = None
        self.last_state: ECAState | None = None
        self.last_decision: InterruptDecision | None = None
        self.structural_time_tracker = (
            StructuralTimeTracker()
            if bool(self.config.structural_time_shadow_enabled)
            else None
        )
        self.last_structural_time_summary: dict[str, Any] = {}
        self.structural_time_shadow_error_count = 0
        self.last_stable_target: dict[str, Any] | None = None
        self.last_stable_action_family: str = ""
        self.last_effective_local_contract_source = self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_NONE
        self.last_effective_local_contract_component_id = ""
        self.last_effective_local_contract_anchor = ""
        self.last_effective_local_target_summary = ""
        self.plan_contract = PlanContract()
        # Typed lock gate counters (v8)
        self._lock_hypothesis_eval_count = 0
        self._lock_hypothesis_pass_count = 0
        self._lock_hypothesis_block_reason_histogram: dict[str, int] = {}
