    def _action_family_from_string(self, value: str | None) -> ActionFamily:
        normalized = str(value or "").strip().lower()
        for family in ActionFamily:
            if family.value == normalized:
                return family
        return ActionFamily.UNKNOWN

    def _required_family_from_latch(self) -> ActionFamily:
        if not self.control_hypothesis_latch:
            return ActionFamily.UNKNOWN
        return self._action_family_from_string(self.control_hypothesis_latch.get("required_action_family"))

    def _latest_agent_action_name(self, agent: Any) -> str:
        if hasattr(agent, "get_recent_history"):
            recent_history = agent.get_recent_history(limit=1) or []
            if recent_history:
                return str((recent_history[-1] or {}).get("action", "") or "")
        if hasattr(agent, "export_eca_view"):
            view = agent.export_eca_view() or {}
            recent_history = view.get("recent_history") or []
            if recent_history:
                return str((recent_history[-1] or {}).get("action", "") or "")
        return ""

    def _repair_gate_operator_from_action(self, action_name: str | None) -> str:
        normalized = str(action_name or "").strip().upper()
        if normalized == "ACTION6":
            return "click"
        if normalized in {"ACTION1", "ACTION2", "ACTION3", "ACTION4"}:
            return "move"
        if normalized == "ACTION5":
            return "auxiliary"
        if normalized:
            return normalized.lower()
        return ""

    def _repair_gate_proposal_from_local_result(
        self,
        result: LocalControllerResult | None,
        *,
        state: ECAState,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        if result is None:
            return {}, {"phase": str(getattr(state, "arc_state", "") or "")}

        action = None
        if getattr(result, "actions", None):
            action = list(result.actions or [])[0]
        action_name = str(getattr(action, "action_name", "") or "").strip().upper()
        payload = dict(getattr(action, "parameters", {}) or {}) if action is not None else {}

        selected = getattr(result, "selected_target", None)
        resolution = getattr(result, "resolution", None)
        if selected is None and resolution is not None:
            selected = getattr(resolution, "selected", None)
        micro_plan = getattr(result, "micro_plan", None)

        selected_family = str(getattr(selected, "action_family", "") or "").strip()
        micro_family = str(getattr(micro_plan, "family", "") or "").strip()
        control_operator = selected_family or micro_family or self._repair_gate_operator_from_action(action_name)
        target_translation_status = "no_action"
        if action_name and selected is not None:
            target_translation_status = "goal_objective_bound"
        elif action_name:
            target_translation_status = "action_only"

        features: dict[str, Any] = {
            "phase": str(getattr(state, "arc_state", "") or ""),
            "level_number": int(getattr(state, "level_number", 0) or 0),
            "score": int(getattr(state, "score", 0) or 0),
            "score_delta": int(getattr(state, "score_delta", 0) or 0),
            "step_index_bucket": str(int(getattr(state, "step_index", 0) or 0) // 10),
            "queue_remaining_bucket": str(int(getattr(state, "queue_remaining", 0) or 0) // 5),
            "primitive": str(getattr(action, "reason", "") or getattr(micro_plan, "reason", "") or ""),
            "control_solver_family": micro_family
            or str(getattr(selected, "source", "") or "")
            or str(getattr(resolution, "resolution_source", "") or ""),
            "control_operator": control_operator,
            "target_translation_status": target_translation_status,
        }
        selected_recent_churn_ctx: dict[str, Any] = {}
        if selected is not None:
            features["selected_target_source"] = str(getattr(selected, "source", "") or "")
            features["selected_target_component_id"] = str(getattr(selected, "component_id", "") or "")
            features["selected_target_anchor"] = str(getattr(selected, "anchor_key", "") or "")
            features["selected_target_action_family"] = str(getattr(selected, "action_family", "") or "")
            features["selected_target_action_name"] = str(getattr(selected, "action_name", "") or "")
            try:
                features["selected_target_center_row"] = int(getattr(selected, "center_row", 0) or 0)
                features["selected_target_center_col"] = int(getattr(selected, "center_col", 0) or 0)
            except (TypeError, ValueError):
                pass
            try:
                features["selected_target_resolver_score_bucket"] = str(
                    int(float(getattr(selected, "resolver_score", 0.0) or 0.0) * 10.0)
                )
            except (TypeError, ValueError):
                pass
            if resolution is not None and getattr(resolution, "all_scored", None):
                scored = list(getattr(resolution, "all_scored", []) or [])
                features["candidate_count"] = int(len(scored))
                selected_component = str(getattr(selected, "component_id", "") or "")
                selected_anchor = str(getattr(selected, "anchor_key", "") or "")
                for idx, candidate in enumerate(scored):
                    if (
                        selected_component
                        and str(getattr(candidate, "component_id", "") or "") == selected_component
                    ) or (
                        selected_anchor
                        and str(getattr(candidate, "anchor_key", "") or "") == selected_anchor
                    ):
                        features["selected_target_rank"] = int(idx)
                        break
            try:
                selected_recent_churn_ctx = self._recent_selected_target_cluster_turnover_context(
                    state=state,
                    current_target={
                        "component_id": str(getattr(selected, "component_id", "") or ""),
                        "anchor_key": str(getattr(selected, "anchor_key", "") or ""),
                    },
                )
            except Exception:
                selected_recent_churn_ctx = {}
        features["selected_target_recent_churn_selected_count"] = int(
            selected_recent_churn_ctx.get("selected_target_count", 0) or 0
        )
        features["selected_target_recent_churn_unique_target_count"] = int(
            selected_recent_churn_ctx.get("unique_target_count", 0) or 0
        )
        features["selected_target_recent_churn_no_score_change_count"] = int(
            selected_recent_churn_ctx.get("no_score_change_count", 0) or 0
        )
        features["selected_target_recent_churn_score_gain_count"] = int(
            selected_recent_churn_ctx.get("score_gain_count", 0) or 0
        )
        if action_name:
            features["eca_action"] = action_name

        proposal = {
            "action": action_name,
            "payload": payload,
            "target_kind": control_operator,
        }
        return proposal, features

    def _update_structural_time_shadow(
        self,
        *,
        agent: Any,
        observation: dict[str, Any] | None,
        level_changed: bool,
    ) -> dict[str, Any]:
        self.last_structural_time_summary = {}
        if self.structural_time_tracker is None:
            return {}
        try:
            if level_changed:
                self.structural_time_tracker.reset()
            build_goal_conditioned_state(
                observation=observation,
                tracker=self.structural_time_tracker,
                action=self._latest_agent_action_name(agent),
            )
            self.last_structural_time_summary = dict(
                self.structural_time_tracker.to_summary_dict() or {}
            )
        except Exception as exc:
            self.structural_time_shadow_error_count += 1
            self.last_structural_time_summary = {}
            log.warning(
                "[eca] structural_time shadow update failed; continuing without GCSTM shadow: %s",
                exc,
            )
        return self.last_structural_time_summary

    @property
    def enabled(self) -> bool:
        return self.config.enabled

    @property
    def mode(self) -> str:
        return self.config.mode

    def observe(self, *, agent: Any, observation: dict[str, Any] | None, level_number: int) -> AnxietySnapshot | None:
        if not self.enabled:
            return None
        state = build_eca_state(
            agent=agent,
            observation=observation,
            level_number=level_number,
            max_actions=self.max_actions,
            analyzer_calls=self.analyzer_calls,
            interrupt_count=self.interrupt_count,
        )
        _allowed_actions = _normalized_available_actions_from_observation(
            observation,
            state=state,
        )
        self.last_available_actions = list(_allowed_actions)
        self._record_no_change_click_anchor_history(state=state)
        previous_state = (
            self.last_state
            if self.last_state is not None and self.last_state.level_number == state.level_number
            else None
        )
        previous_step_index = previous_state.step_index if previous_state is not None else None
        level_changed = state.level_number != self.last_level_number
        self.last_clicked_component_ids = set(self._clicked_component_ids(agent))
        self.last_changed_clicked_component_ids = set(self._clicked_changed_component_ids(agent))
        try:
            self.last_bootstrap_focus_components = list(
                self._pick_focus_components(state, agent=agent, limit=16)
            )
        except Exception:
            self.last_bootstrap_focus_components = []
        self._update_structural_time_shadow(
            agent=agent,
            observation=observation,
            level_changed=level_changed,
        )
        snapshot = compute_anxiety_snapshot(
            state=state,
            weights=self.config.weights,
            plan_generation=self.plan_generation,
            high_threshold=self.config.threshold_high,
            structural_context=self._build_structural_context(
                state=state,
                level_changed=level_changed,
            ),
        )
        if level_changed:
            self.last_clicked_component_ids = set()
            self.last_bootstrap_focus_components = []
            self.level_interrupt_count = 0
            self.soft_interrupt_count = 0
            self.frontier_nodes = {}
            self.last_frontier_node = None
            self.last_promotion_event = None
            self.last_frontier_region_key = ""
            self.active_frontier_contract = FrontierContract()
            self.active_frontier_switch_count = 0
            self.target_anchor_click_no_change_history = {}
            self.last_anchor_no_change_click_history_marker = None
            self.local_effect_ledger = {}
            self.local_effect_family_ledger = {}
            self.last_local_effect_event = {}
            self.last_local_effect_family_event = {}
            self.last_local_effect_marker = None
            self.last_local_effect_attribution = {}
            self.last_delayed_effect_event = {}
            self.local_effect_event_count = 0
            self.local_transition_frontier = []
            self.last_local_transition_frontier_event = {}
            self.local_transition_frontier_event_count = 0
            self.local_transition_frontier_broad_suppressed_count = 0
            self.local_transition_frontier_consumed_count = 0
            self.local_transition_relay_event_count = 0
            self.local_click_relation_ledger = {}
            self.local_click_relation_event_count = 0
            self.rule_discovery.reset_level()
            self.last_pending_detector_dead_tail_ratio = 0.0
            self.last_pending_detector_terminal_like_reason_count_topk = 0
            self.last_pending_detector_selected_target_empty_with_candidate_pool = False
