    def _attempt_protected_hedge_post_final_reclaim_hold_reentry_from_ticket(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return False
        current_claim_state = self._protected_hedge_runtime_claim_state(contract)
        if current_claim_state != self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE:
            return False
        if not self._post_final_packet_ticket_matches_contract(contract):
            return False
        entered = self._enter_protected_hedge_post_final_reclaim_hold(step_index=step_index)
        if entered:
            self.last_post_final_packet_ticket_reentered = True
            self.post_final_packet_ticket_reentry_count += 1
        return entered

    def _attempt_protected_hedge_post_final_reclaim_hold_entry_from_final_reclaimable(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return False
        if (
            self._protected_hedge_runtime_claim_state(contract)
            != self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE
        ):
            return False
        effective_step_index = int(
            step_index
            if step_index is not None
            else (self.last_state.step_index if self.last_state is not None else -1)
        )
        entered_step_idx = int(contract.get("final_reclaimable_entered_step_idx", -1) or -1)
        if entered_step_idx < 0 or effective_step_index <= entered_step_idx:
            return False
        if not bool(self.last_protected_hedge_visible or self._protected_hedge_contract_visible(contract)):
            return False
        self._record_final_reclaim_exit_reason("final_reclaim_queue_exhausted_to_post_final_hold")
        return self._enter_protected_hedge_post_final_reclaim_hold(step_index=effective_step_index)

    def _expire_post_final_shared_continuation_ticket(
        self,
        *,
        reason: str = "",
        step_index: int | None = None,
    ) -> None:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        ticket["expired_turn"] = effective_step_index
        if reason:
            ticket["expired_reason"] = str(reason or "")
            if int(ticket.get("attach_count", 0) or 0) <= 0:
                self._record_post_final_shared_continuation_ticket_attach_skip_reason(
                    f"expired:{str(reason or '')}"
                )
        self.last_post_final_shared_continuation_ticket = None
        self.last_post_final_shared_continuation_ticket_expired = True
        self.post_final_shared_continuation_ticket_expire_count += 1
        self.last_post_final_shared_continuation_ticket_source = ""

    def _issue_post_final_shared_continuation_ticket(
        self,
        *,
        contract: dict[str, Any] | None = None,
        source: str = "",
        step_index: int | None = None,
    ) -> None:
        item = dict(contract if contract is not None else self.last_protected_hedge_contract or {})
        summary = dict(self.last_selected_target_summary or {})
        rerank_seed = self._recent_post_final_shared_rerank_top_candidate(step_index=step_index)
        seed_summary = dict(rerank_seed or summary)
        component_id = str(
            seed_summary.get("component_id", "")
            or summary.get("component_id", "")
            or item.get("component_id", "")
            or ""
        )
        anchor_key = str(
            seed_summary.get("anchor_key", "")
            or summary.get("anchor_key", "")
            or self._protected_hedge_contract_key(item)
            or ""
        )
        if not component_id and not anchor_key:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        candidate_snapshot = dict(rerank_seed or {})
        if not candidate_snapshot:
            candidate_snapshot = {
                "candidate_id": str(summary.get("candidate_id", "") or ""),
                "level_idx": int(self.last_state.level_number if self.last_state is not None else -1),
                "component_id": component_id,
                "anchor_key": anchor_key,
                "center_row": int(item.get("center_row", 0) or 0),
                "center_col": int(item.get("center_col", 0) or 0),
                "source": str(summary.get("source", "") or ""),
                "family": "move",
                "admission_score": float(summary.get("admission_score", 0.0) or 0.0),
                "suggested_probe_reason": str(
                    summary.get("suggested_probe_reason", "") or "post_final_shared_continuation"
                ),
            }
        self.last_post_final_shared_continuation_ticket = {
            "component_id": component_id,
            "anchor_key": anchor_key,
            "candidate_id": str(
                seed_summary.get("candidate_id", "") or summary.get("candidate_id", "") or ""
            ),
            "source": str(seed_summary.get("source", "") or summary.get("source", "") or ""),
            "suggested_probe_reason": str(
                seed_summary.get("suggested_probe_reason", "")
                or summary.get("suggested_probe_reason", "")
                or "post_final_shared_continuation"
            ),
            "confidence": str(seed_summary.get("confidence", "") or summary.get("confidence", "") or "low"),
            "seed_kind": "shared_rerank" if rerank_seed else "selected_target_summary",
            "candidate_snapshot": candidate_snapshot,
            "issued_turn": effective_step_index,
            "expires_turn": (
                effective_step_index + self.TARGET_POST_FINAL_SHARED_CONTINUATION_TICKET_TTL_STEPS
            ),
            "blocked_grace_used": False,
            "blocked_grace_until": -1,
            "blocked_grace_reason": "",
            "attach_count": 0,
            "last_attached_turn": -10_000,
            "open_reason": str(source or ""),
            "level_idx": int(self.last_state.level_number if self.last_state is not None else -1),
        }
        self.last_post_final_shared_continuation_ticket_source = str(source or "")
        self.last_post_final_shared_continuation_ticket_attach_skip_reason = ""
        self.last_post_final_shared_continuation_ticket_issued = True
        self.post_final_shared_continuation_ticket_issue_count += 1
        if source:
            self.post_final_shared_continuation_ticket_source_histogram[str(source)] = int(
                self.post_final_shared_continuation_ticket_source_histogram.get(str(source), 0) or 0
            ) + 1
        self._issue_post_final_shared_continuation_lock(
            ticket=dict(self.last_post_final_shared_continuation_ticket or {}),
            step_index=effective_step_index,
            selected_target_summary=dict(seed_summary or summary),
            candidate_snapshot=dict(candidate_snapshot or {}),
        )
        normalized_source = str(source or "")
        if (
            rerank_seed
            and normalized_source.startswith("shared_post_final_shared_rerank_")
            and normalized_source.endswith("_to_reclaimable")
        ):
            self._issue_post_final_shared_continuation_target_psa_credit(
                ticket=dict(self.last_post_final_shared_continuation_ticket or {}),
                step_index=effective_step_index,
                source_override="shared_exit_rerank_seed",
            )

    def _post_final_shared_continuation_ticket_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket:
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        level_idx = int(ticket.get("level_idx", -1) or -1)
        if self.last_state is not None and level_idx >= 0 and int(self.last_state.level_number) != level_idx:
            return False
        expires_turn = int(ticket.get("expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _post_final_shared_continuation_ticket_blocked_grace_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket or not bool(ticket.get("blocked_grace_used", False)):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        grace_until = int(ticket.get("blocked_grace_until", -1) or -1)
        return grace_until >= 0 and effective_step_index <= grace_until

    def _post_final_shared_continuation_ticket_blocked_grace_reason(
        self,
        *,
        state: ECAState,
    ) -> str:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket:
            return ""
        if int(ticket.get("attach_count", 0) or 0) > 0:
            return ""
        component_id = str(ticket.get("component_id", "") or "")
        anchor_key = str(ticket.get("anchor_key", "") or "")
        component_reason = str((self.target_blacklist.get(component_id) or {}).get("reason", "") or "")
        anchor_reason = str((self.target_anchor_blacklist.get(anchor_key) or {}).get("reason", "") or "")
        blocked_reason = component_reason or anchor_reason
        if blocked_reason not in {
            "fresh_target_minimal_probe_exhausted",
            "target_move_probe_exhausted",
            "target_family_probe_exhausted",
            "target_click_probe_exhausted",
        }:
            return ""
        if bool(ticket.get("blocked_grace_used", False)):
            return ""
        seed_kind = str(ticket.get("seed_kind", "") or "")
        if seed_kind != "shared_rerank" and not self._post_final_shared_recent_rerank_support(
            step_index=int(state.step_index)
        ):
            return ""
        return blocked_reason

    def _post_final_shared_continuation_ticket_matches_target(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
    ) -> bool:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket or not local_target:
            return False
        ticket_component_id = str(ticket.get("component_id", "") or "")
        ticket_anchor_key = str(ticket.get("anchor_key", "") or "")
        component_id = str(local_target.get("component_id", "") or "")
        anchor_key = self._anchor_key(level_number=state.level_number, component=local_target)
        return bool(
            (ticket_component_id and component_id and ticket_component_id == component_id)
            or (ticket_anchor_key and anchor_key and ticket_anchor_key == anchor_key)
        )

    def _selected_target_summary_matches_post_final_shared_continuation_identity(
        self,
        *,
        selected_target_summary: SelectedTargetSummary,
        item: dict[str, Any],
    ) -> bool:
        summary_component_id = str(selected_target_summary.component_id or "")
        summary_anchor_key = str(selected_target_summary.anchor_key or "")
        summary_candidate_id = str(selected_target_summary.candidate_id or "")
        item_component_id = str(item.get("component_id", "") or "")
        item_anchor_key = str(item.get("anchor_key", "") or "")
        item_candidate_id = str(item.get("candidate_id", "") or "")
        return bool(
            (summary_component_id and item_component_id and summary_component_id == item_component_id)
            or (summary_anchor_key and item_anchor_key and summary_anchor_key == item_anchor_key)
            or (summary_candidate_id and item_candidate_id and summary_candidate_id == item_candidate_id)
        )

    def _maybe_sync_post_final_shared_continuation_with_selected_target(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
    ) -> None:
        if selected_target_summary is None:
            return
        if self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        ):
            return
        effective_step_index = int(state.step_index)
        summary_payload = selected_target_summary.to_dict()
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if (
            ticket
            and self._post_final_shared_continuation_ticket_active(step_index=effective_step_index)
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=ticket,
            )
        ):
            if int(ticket.get("attach_count", 0) or 0) <= 0:
                self._mark_post_final_shared_continuation_ticket_attached(
                    step_index=effective_step_index,
                    selected_target_summary=summary_payload,
                    candidate_snapshot=dict(ticket.get("candidate_snapshot") or {}),
                )
                return
            if not self._post_final_shared_continuation_lock_active(
                step_index=effective_step_index
            ):
                self._issue_post_final_shared_continuation_lock(
                    ticket=ticket,
                    step_index=effective_step_index,
                    selected_target_summary=summary_payload,
                    candidate_snapshot=dict(ticket.get("candidate_snapshot") or {}),
                )
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if (
            lock_item
            and self._post_final_shared_continuation_lock_active(step_index=effective_step_index)
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=lock_item,
            )
        ):
            self._consume_post_final_shared_continuation_lock(
                step_index=effective_step_index,
            )
            self._record_post_final_shared_continuation_lock_skip_reason("")
            self._issue_post_final_shared_continuation_target_psa_credit(
                ticket=lock_item,
                step_index=effective_step_index,
                source_override="continuation_lock_attach",
            )
            self._apply_post_final_shared_continuation_probe_refresh(
                step_index=effective_step_index,
                selected_target_summary=summary_payload,
                reason="post_final_shared_continuation_lock_attach",
            )

    def _maybe_sync_post_final_shared_continuation_from_last_selected_target_summary(
        self,
        *,
        state: ECAState,
    ) -> None:
        selected_target_summary = self._last_selected_target_summary_object()
        if selected_target_summary is None:
            return
        self._maybe_sync_post_final_shared_continuation_with_selected_target(
            state=state,
            selected_target_summary=selected_target_summary,
        )

    def _recent_post_final_shared_after_exit_durability_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        last_exit_step_idx = int(self.last_post_final_shared_exit_step_idx or -1)
        if last_exit_step_idx < 0:
            return False
        if bool((self.last_protected_hedge_contract or {}).get("post_final_shared_active", False)):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        return effective_step_index <= (
            last_exit_step_idx + self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_DURABILITY_STEPS
        )

    def _should_promote_reconstructed_post_final_shared_selected_target(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
    ) -> bool:
        if selected_target_summary is None:
            return False
        if self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        ):
            return False
        effective_step_index = int(state.step_index)
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if (
            ticket
            and self._post_final_shared_continuation_ticket_active(step_index=effective_step_index)
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=ticket,
            )
        ):
            return True
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        return bool(
            lock_item
            and self._post_final_shared_continuation_lock_active(step_index=effective_step_index)
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=lock_item,
            )
        )

    def _maybe_apply_post_final_shared_continuation_ticket_psa_bypass(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
        current_target_psa_dead_end: bool,
        current_target_psa_state: str,
        current_target_verify_budget: int,
        forced_click_ban_current_target: bool,
        target_viability_reason: str,
        target_viability_drop_reason: str,
    ) -> tuple[bool, str, int, bool]:
        selected_target_summary = self._last_selected_target_summary_object()
        if selected_target_summary is None and self._post_final_shared_retained_route_anchor_active(
            step_index=int(state.step_index)
        ):
            selected_target_summary = self._selected_target_summary_from_retained_route_anchor()
        retained_anchor_matches_state_selected_target, _ = (
            self._post_final_shared_retained_route_anchor_matches_state_selected_target(
                state=state,
            )
        )
        retained_anchor_matches_current_contract, _ = (
            self._post_final_shared_retained_route_anchor_matches_current_contract()
        )
        retained_anchor_matches_effective_local_contract, _ = (
            self._post_final_shared_retained_route_anchor_matches_effective_local_contract()
        )
        retained_anchor_matches_active_continuation_identity, _ = (
            self._post_final_shared_retained_route_anchor_matches_active_continuation_identity(
                step_index=int(state.step_index),
            )
        )
        (
            retained_anchor_late_exit_class,
            retained_anchor_same_route,
            retained_anchor_continuity_score,
        ) = self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
            state=state,
            local_target=local_target,
            selected_target_summary=selected_target_summary,
            target_viability_reason=target_viability_reason,
            target_viability_drop_reason=target_viability_drop_reason,
        )
        self.last_post_final_shared_after_exit_psa_late_exit_class = (
            retained_anchor_late_exit_class
        )
        self.last_post_final_shared_after_exit_same_route_anchor = bool(
            retained_anchor_same_route
        )
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            float(retained_anchor_continuity_score or 0.0),
            3,
        )
        if (
            not local_target
            and selected_target_summary is None
            and not retained_anchor_matches_state_selected_target
            and not retained_anchor_matches_effective_local_contract
            and not retained_anchor_matches_active_continuation_identity
            and not retained_anchor_matches_current_contract
        ):
            return (
                current_target_psa_dead_end,
                current_target_psa_state,
                current_target_verify_budget,
                forced_click_ban_current_target,
            )
        ticket_active = self._post_final_shared_continuation_ticket_active(
            step_index=int(state.step_index)
        )
        lock_active = self._post_final_shared_continuation_lock_active(
            step_index=int(state.step_index)
        )
        ticket_blocked_grace_active = self._post_final_shared_continuation_ticket_blocked_grace_active(
            step_index=int(state.step_index)
        )
        target_psa_credit_active = self._post_final_shared_continuation_target_psa_credit_active(
            step_index=int(state.step_index)
        )
        ticket_matches_target = self._post_final_shared_continuation_ticket_matches_target(
            state=state,
            local_target=local_target,
        ) if local_target else False
        credit_matches_target = self._post_final_shared_continuation_target_psa_credit_matches_target(
            state=state,
            local_target=local_target,
        ) if local_target else False
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        ticket_matches_selected_target = bool(
            selected_target_summary is not None
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=ticket,
            )
        )
        credit_item = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        credit_matches_selected_target = bool(
            selected_target_summary is not None
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=credit_item,
            )
        )
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        lock_matches_target = bool(
            local_target
            and self._post_final_shared_continuation_lock_matches_identity(
                component_id=str(local_target.get("component_id", "") or ""),
                anchor_key=self._anchor_key(level_number=state.level_number, component=local_target),
            )
        )
        lock_matches_selected_target = bool(
            selected_target_summary is not None
            and self._selected_target_summary_matches_post_final_shared_continuation_identity(
                selected_target_summary=selected_target_summary,
                item=lock_item,
            )
        )
        ticket_direct_viability_credit_active = bool(
            ticket_active
            and (ticket_matches_target or ticket_matches_selected_target)
            and str(ticket.get("seed_kind", "") or "") == "shared_rerank"
            and (
                str(target_viability_drop_reason or "") == "fresh_target_minimal_probe_exhausted"
                or str(target_viability_reason or "") == "psa_sweep_dead"
            )
        )
        lock_direct_viability_credit_active = bool(
            lock_active
            and (lock_matches_target or lock_matches_selected_target)
            and str(lock_item.get("seed_kind", "") or "") in {"shared_rerank", "selected_target_summary"}
            and (
                str(target_viability_drop_reason or "") in {
                    "fresh_target_minimal_probe_exhausted",
                    "target_move_probe_exhausted",
                    "target_family_probe_exhausted",
                }
                or str(target_viability_reason or "") == "psa_sweep_dead"
            )
        )
        recent_shared_exit_durability_active = bool(
            self._recent_post_final_shared_after_exit_durability_active(step_index=int(state.step_index))
            and (bool(local_target) or selected_target_summary is not None)
            and (
                str(target_viability_drop_reason or "") in {
                    "fresh_target_minimal_probe_exhausted",
                    "target_move_probe_exhausted",
                    "target_family_probe_exhausted",
                }
                or str(target_viability_reason or "") in {
                    "psa_anchor_locked_dead",
                    "psa_dead_end",
                    "psa_sweep_dead",
                }
            )
        )
        same_step_continuation_refresh_active = bool(
            (
                self.last_post_final_shared_continuation_lock_consumed
                or self.last_post_final_shared_continuation_ticket_attached
                or self.last_post_final_shared_continuation_target_psa_credit_issued
            )
            and (bool(local_target) or selected_target_summary is not None)
            and (
                str(target_viability_drop_reason or "") in {
                    "fresh_target_minimal_probe_exhausted",
                    "target_move_probe_exhausted",
                    "target_family_probe_exhausted",
                }
                or str(target_viability_reason or "") in {
                    "psa_anchor_locked_dead",
                    "psa_dead_end",
                    "psa_sweep_dead",
                }
            )
        )
        retained_anchor_probe_continuity_active = bool(
            retained_anchor_late_exit_class == "recoverable_exhaustion"
            and retained_anchor_same_route
            and (
                self._record_post_final_shared_after_exit_same_route_anchor_event(
                    step_index=int(state.step_index),
                )
                is None
            )
            and self._apply_post_final_shared_probe_continuity_from_retained_anchor(
                state=state,
                local_target=local_target,
                selected_target_summary=selected_target_summary,
            )
        )
        same_route_family_probe_carry_active = self._maybe_apply_post_final_shared_same_route_family_probe_carry_after_exit(
            state=state,
            local_target=local_target,
            selected_target_summary=selected_target_summary,
            effective_local_contract_source=str(self.last_effective_local_contract_source or ""),
            effective_local_contract_component_id=str(self.last_effective_local_contract_component_id or ""),
            effective_local_contract_anchor=str(self.last_effective_local_contract_anchor or ""),
            target_viability_reason=target_viability_reason,
            target_viability_drop_reason=target_viability_drop_reason,
            current_target_verify_budget=current_target_verify_budget,
        )
        same_route_move_probe_carry_active = self._maybe_apply_post_final_shared_same_route_move_probe_carry_after_exit(
            state=state,
            local_target=local_target,
            selected_target_summary=selected_target_summary,
            effective_local_contract_source=str(self.last_effective_local_contract_source or ""),
            effective_local_contract_component_id=str(self.last_effective_local_contract_component_id or ""),
            effective_local_contract_anchor=str(self.last_effective_local_contract_anchor or ""),
            target_viability_reason=target_viability_reason,
            target_viability_drop_reason=target_viability_drop_reason,
            current_target_verify_budget=current_target_verify_budget,
        )
        if not (
            (ticket_blocked_grace_active and (ticket_matches_target or ticket_matches_selected_target))
            or ticket_direct_viability_credit_active
            or lock_direct_viability_credit_active
            or recent_shared_exit_durability_active
            or same_step_continuation_refresh_active
            or retained_anchor_probe_continuity_active
            or same_route_family_probe_carry_active
            or same_route_move_probe_carry_active
            or (
                target_psa_credit_active
                and (credit_matches_target or credit_matches_selected_target)
            )
        ):
            return (
                current_target_psa_dead_end,
                current_target_psa_state,
                current_target_verify_budget,
                forced_click_ban_current_target,
            )
        bypass_reason = ""
        if str(target_viability_drop_reason or "") in {
            "fresh_target_minimal_probe_exhausted",
            "target_move_probe_exhausted",
            "target_family_probe_exhausted",
        }:
            bypass_reason = str(target_viability_drop_reason or "")
        elif str(target_viability_reason or "") in {
            "psa_anchor_locked_dead",
            "psa_dead_end",
            "psa_sweep_dead",
        }:
            bypass_reason = str(target_viability_reason or "")
        elif str(current_target_psa_state or "") == self.TARGET_PSA_STATE_COOLDOWN:
            bypass_reason = "psa_cooldown"
        elif bool(current_target_psa_dead_end):
            bypass_reason = "psa_dead_end"
        if not bypass_reason:
            return (
                current_target_psa_dead_end,
                current_target_psa_state,
                current_target_verify_budget,
                forced_click_ban_current_target,
            )
        self._record_post_final_shared_continuation_ticket_psa_bypass(
            reason=bypass_reason,
        )
        if (
            recent_shared_exit_durability_active
            or same_step_continuation_refresh_active
            or retained_anchor_probe_continuity_active
            or same_route_family_probe_carry_active
            or same_route_move_probe_carry_active
        ):
            target_component_id = str(
                (local_target or {}).get("component_id", "")
                or (selected_target_summary.component_id if selected_target_summary is not None else "")
                or ""
            )
            target_anchor_key = str(
                self._anchor_key(level_number=state.level_number, component=local_target)
                if local_target
                else (selected_target_summary.anchor_key if selected_target_summary is not None else "")
                or ""
            )
            if target_component_id:
                self.target_blacklist.pop(target_component_id, None)
            if target_anchor_key:
                self.target_anchor_blacklist.pop(target_anchor_key, None)
        if target_psa_credit_active and (credit_matches_target or credit_matches_selected_target):
            self._consume_post_final_shared_continuation_target_psa_credit(
                step_index=int(state.step_index),
            )
        if (
            recent_shared_exit_durability_active
            or same_step_continuation_refresh_active
            or retained_anchor_probe_continuity_active
            or same_route_family_probe_carry_active
            or same_route_move_probe_carry_active
        ):
            verify_budget_floor = 2 if (same_route_family_probe_carry_active or same_route_move_probe_carry_active) else 1
            return (
                False,
                self.TARGET_PSA_STATE_VERIFY_ONCE,
                max(int(current_target_verify_budget or 0), verify_budget_floor),
                False,
            )
        return False, "", 0, False

    def _mark_post_final_shared_continuation_ticket_attached(
        self,
        *,
        step_index: int | None = None,
        selected_target_summary: dict[str, Any] | None = None,
        candidate_snapshot: dict[str, Any] | None = None,
    ) -> None:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if int(ticket.get("last_attached_turn", -10_000) or -10_000) == effective_step_index:
            return
        ticket["attach_count"] = int(ticket.get("attach_count", 0) or 0) + 1
        ticket["last_attached_turn"] = effective_step_index
        self.last_post_final_shared_continuation_ticket = ticket
        self.last_post_final_shared_continuation_ticket_attached = True
        self.last_post_final_shared_continuation_ticket_attach_skip_reason = ""
        self.post_final_shared_continuation_ticket_attach_count += 1
        self._issue_post_final_shared_continuation_lock(
            ticket=ticket,
            step_index=effective_step_index,
            selected_target_summary=selected_target_summary,
            candidate_snapshot=candidate_snapshot,
        )
        self._issue_post_final_shared_continuation_target_psa_credit(
            ticket=ticket,
            step_index=effective_step_index,
        )

    def _issue_post_final_shared_continuation_target_psa_credit(
        self,
        *,
        ticket: dict[str, Any],
        step_index: int | None = None,
        source_override: str = "",
    ) -> None:
        component_id = str(ticket.get("component_id", "") or "")
        anchor_key = str(ticket.get("anchor_key", "") or "")
        if not component_id and not anchor_key:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        source = str(source_override or "")
        if not source:
            source = str(ticket.get("blocked_grace_reason", "") or "")
            if source:
                source = f"blocked_grace:{source}"
            else:
                source = "continuation_attach"
        self.last_post_final_shared_continuation_target_psa_credit = {
            "component_id": component_id,
            "anchor_key": anchor_key,
            "level_idx": int(ticket.get("level_idx", -1) or -1),
            "issued_turn": effective_step_index,
            "expires_turn": (
                effective_step_index
                + self.TARGET_POST_FINAL_SHARED_CONTINUATION_ATTACHED_PSA_CREDIT_STEPS
            ),
            "source": source,
        }
        self.last_post_final_shared_continuation_target_psa_credit_issued = True
        self.last_post_final_shared_continuation_target_psa_credit_source = source
        self.post_final_shared_continuation_target_psa_credit_issue_count += 1
        self.post_final_shared_continuation_target_psa_credit_source_histogram[source] = int(
            self.post_final_shared_continuation_target_psa_credit_source_histogram.get(source, 0) or 0
        ) + 1
        if source == "shared_exit_rerank_seed":
            self._rearm_post_final_shared_rerank_target_from_credit(ticket=ticket)

    def _rearm_post_final_shared_rerank_target_from_credit(
        self,
        *,
        ticket: dict[str, Any],
    ) -> None:
        state = self.last_state
        if state is None:
            return
        component_id = str(ticket.get("component_id", "") or "")
        anchor_key = str(ticket.get("anchor_key", "") or "")
        if not component_id and not anchor_key:
            return
        component_block = dict(self.target_blacklist.get(component_id) or {})
        anchor_block = dict(self.target_anchor_blacklist.get(anchor_key) or {})
        block_reason = str(component_block.get("reason", "") or anchor_block.get("reason", "") or "")
        if block_reason not in {
            "fresh_target_minimal_probe_exhausted",
            "target_move_probe_exhausted",
            "target_family_probe_exhausted",
            "target_click_probe_exhausted",
        }:
            return
        if component_id:
            self.target_blacklist.pop(component_id, None)
        if anchor_key:
            self.target_anchor_blacklist.pop(anchor_key, None)
        psa_state = self._target_psa_state(component_id)
        viability = {
            "psa_reason": str(
                psa_state.get("psa_reason", "") or component_block.get("psa_reason", "") or "psa_dead_end"
            ),
            "viability_score": float(
                psa_state.get("viability_score", 0.0) or component_block.get("viability_score", 0.0) or 0.0
            ),
        }
        self._arm_target_verify_once(
            component_id=component_id,
            viability=viability,
            state=state,
        )

    def _issue_post_final_shared_continuation_lock(
        self,
        *,
        ticket: dict[str, Any],
        step_index: int | None = None,
        selected_target_summary: dict[str, Any] | None = None,
        candidate_snapshot: dict[str, Any] | None = None,
    ) -> None:
        component_id = str(
            (selected_target_summary or {}).get("component_id", "")
            or ticket.get("component_id", "")
            or ""
        )
        anchor_key = str(
            (selected_target_summary or {}).get("anchor_key", "")
            or ticket.get("anchor_key", "")
            or ""
        )
        if not component_id and not anchor_key:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        snapshot = dict(candidate_snapshot or {})
        if not snapshot:
            snapshot = dict(ticket.get("candidate_snapshot") or {})
        if not snapshot:
            snapshot = {
                "candidate_id": str(
                    (selected_target_summary or {}).get("candidate_id", "")
                    or ticket.get("candidate_id", "")
                    or ""
                ),
                "level_idx": int(ticket.get("level_idx", -1) or -1),
                "component_id": component_id,
                "anchor_key": anchor_key,
                "source": str(
                    (selected_target_summary or {}).get("source", "")
                    or ticket.get("source", "")
                    or ""
                ),
                "family": "move",
                "admission_score": float(
                    (selected_target_summary or {}).get("admission_score", 0.0)
                    or (ticket.get("candidate_snapshot") or {}).get("admission_score", 0.0)
                    or 0.0
                ),
                "suggested_probe_reason": str(
                    (selected_target_summary or {}).get("suggested_probe_reason", "")
                    or ticket.get("suggested_probe_reason", "")
                    or "post_final_shared_continuation_lock"
                ),
            }
        source = str(ticket.get("open_reason", "") or "continuation_attach")
        existing = dict(self.last_post_final_shared_continuation_lock or {})
        if existing:
            same_identity = bool(
                (
                    component_id
                    and str(existing.get("component_id", "") or "") == component_id
                )
                or (
                    anchor_key
                    and str(existing.get("anchor_key", "") or "") == anchor_key
                )
            )
            same_turn = int(existing.get("issued_turn", -10_000) or -10_000) == effective_step_index
            if same_identity and same_turn:
                existing.update(
                    {
                        "candidate_id": str(
                            (selected_target_summary or {}).get("candidate_id", "")
                            or snapshot.get("candidate_id", "")
                            or ticket.get("candidate_id", "")
                            or ""
                        ),
                        "source": str(
                            (selected_target_summary or {}).get("source", "")
                            or snapshot.get("source", "")
                            or ticket.get("source", "")
                            or ""
                        ),
                        "suggested_probe_reason": str(
                            (selected_target_summary or {}).get("suggested_probe_reason", "")
                            or snapshot.get("suggested_probe_reason", "")
                            or ticket.get("suggested_probe_reason", "")
                            or "post_final_shared_continuation_lock"
                        ),
                        "confidence": str(
                            (selected_target_summary or {}).get("confidence", "")
                            or ticket.get("confidence", "")
                            or "low"
                        ),
                        "seed_kind": str(ticket.get("seed_kind", "") or existing.get("seed_kind", "") or "continuation_attach"),
                        "candidate_snapshot": snapshot,
                        "expires_turn": max(
                            int(existing.get("expires_turn", -1) or -1),
                            effective_step_index + self.TARGET_POST_FINAL_SHARED_CONTINUATION_LOCK_TTL_STEPS,
                        ),
                        "attach_count": max(
                            int(existing.get("attach_count", 0) or 0),
                            int(ticket.get("attach_count", 0) or 0),
                        ),
                        "open_reason": source,
                        "level_idx": int(ticket.get("level_idx", -1) or -1),
                    }
                )
                self.last_post_final_shared_continuation_lock = existing
                self.last_post_final_shared_continuation_lock_source = source
                self.last_post_final_shared_continuation_lock_skip_reason = ""
                self.last_post_final_shared_continuation_lock_issued = True
                return
        self.last_post_final_shared_continuation_lock = {
            "component_id": component_id,
            "anchor_key": anchor_key,
            "candidate_id": str(
                (selected_target_summary or {}).get("candidate_id", "")
                or snapshot.get("candidate_id", "")
                or ticket.get("candidate_id", "")
                or ""
            ),
            "source": str(
                (selected_target_summary or {}).get("source", "")
                or snapshot.get("source", "")
                or ticket.get("source", "")
                or ""
            ),
            "suggested_probe_reason": str(
                (selected_target_summary or {}).get("suggested_probe_reason", "")
                or snapshot.get("suggested_probe_reason", "")
                or ticket.get("suggested_probe_reason", "")
                or "post_final_shared_continuation_lock"
            ),
            "confidence": str(
                (selected_target_summary or {}).get("confidence", "")
                or ticket.get("confidence", "")
                or "low"
            ),
            "seed_kind": str(ticket.get("seed_kind", "") or "continuation_attach"),
            "candidate_snapshot": snapshot,
            "issued_turn": effective_step_index,
            "expires_turn": (
                effective_step_index + self.TARGET_POST_FINAL_SHARED_CONTINUATION_LOCK_TTL_STEPS
            ),
            "attach_count": int(ticket.get("attach_count", 0) or 0),
            "open_reason": source,
            "level_idx": int(ticket.get("level_idx", -1) or -1),
        }
        self.last_post_final_shared_continuation_lock_source = source
        self.last_post_final_shared_continuation_lock_skip_reason = ""
        self.last_post_final_shared_continuation_lock_issued = True
        self.post_final_shared_continuation_lock_issue_count += 1
        self.post_final_shared_continuation_lock_source_histogram[source] = int(
            self.post_final_shared_continuation_lock_source_histogram.get(source, 0) or 0
        ) + 1

    def _post_final_shared_continuation_lock_matches_identity(
        self,
        *,
        component_id: str = "",
        anchor_key: str = "",
    ) -> bool:
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if not lock_item:
            return False
        lock_component_id = str(lock_item.get("component_id", "") or "")
        lock_anchor_key = str(lock_item.get("anchor_key", "") or "")
        return bool(
            (component_id and lock_component_id and component_id == lock_component_id)
            or (anchor_key and lock_anchor_key and anchor_key == lock_anchor_key)
        )

    def _expire_post_final_shared_continuation_lock(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if not lock_item:
            return
        _ = int(step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1))
        self.last_post_final_shared_continuation_lock = None
        self.last_post_final_shared_continuation_lock_expired = True
        self.post_final_shared_continuation_lock_expire_count += 1
        self.last_post_final_shared_continuation_lock_source = ""

    def _post_final_shared_continuation_lock_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if not lock_item:
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        level_idx = int(lock_item.get("level_idx", -1) or -1)
        if self.last_state is not None and level_idx >= 0 and int(self.last_state.level_number) != level_idx:
            return False
        expires_turn = int(lock_item.get("expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _consume_post_final_shared_continuation_lock(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if not lock_item:
            return
        _ = int(step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1))
        self.last_post_final_shared_continuation_lock = None
        self.last_post_final_shared_continuation_lock_consumed = True
        self.post_final_shared_continuation_lock_consume_count += 1
        self.last_post_final_shared_continuation_lock_source = ""

    def _refresh_post_final_shared_continuation_lock(
        self,
        *,
        state: ECAState,
    ) -> None:
        lock_item = dict(self.last_post_final_shared_continuation_lock or {})
        if not lock_item:
            return
        if int(lock_item.get("level_idx", state.level_number) or state.level_number) != int(state.level_number):
            self._expire_post_final_shared_continuation_lock(step_index=int(state.step_index))
            return
        expires_turn = int(lock_item.get("expires_turn", -1) or -1)
        if expires_turn >= 0 and int(state.step_index) > expires_turn:
            self._expire_post_final_shared_continuation_lock(step_index=int(state.step_index))
            return
        summary = dict(self.last_selected_target_summary or {})
        if self._post_final_shared_continuation_lock_matches_identity(
            component_id=str(summary.get("component_id", "") or ""),
            anchor_key=str(summary.get("anchor_key", "") or ""),
        ):
            lock_item["expires_turn"] = max(
                int(lock_item.get("expires_turn", -1) or -1),
                int(state.step_index) + self.TARGET_POST_FINAL_SHARED_CONTINUATION_LOCK_TTL_STEPS,
            )
            self.last_post_final_shared_continuation_lock = lock_item
            return
        stable_target = dict(self.last_stable_target or {})
        if self._post_final_shared_continuation_lock_matches_identity(
            component_id=str(stable_target.get("component_id", "") or ""),
            anchor_key=str(stable_target.get("anchor_key", "") or ""),
        ):
            lock_item["expires_turn"] = max(
                int(lock_item.get("expires_turn", -1) or -1),
                int(state.step_index) + self.TARGET_POST_FINAL_SHARED_CONTINUATION_LOCK_TTL_STEPS,
            )
            self.last_post_final_shared_continuation_lock = lock_item

    def _expire_post_final_shared_continuation_target_psa_credit(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        credit = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        if not credit:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        credit["expired_turn"] = effective_step_index
        self.last_post_final_shared_continuation_target_psa_credit = None
        self.last_post_final_shared_continuation_target_psa_credit_expired = True
        self.post_final_shared_continuation_target_psa_credit_expire_count += 1

    def _post_final_shared_continuation_target_psa_credit_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        credit = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        if not credit:
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        level_idx = int(credit.get("level_idx", -1) or -1)
        if self.last_state is not None and level_idx >= 0 and int(self.last_state.level_number) != level_idx:
            return False
        expires_turn = int(credit.get("expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _post_final_shared_continuation_target_psa_credit_matches_target(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
    ) -> bool:
        credit = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        if not credit or not local_target:
            return False
        credit_component_id = str(credit.get("component_id", "") or "")
        credit_anchor_key = str(credit.get("anchor_key", "") or "")
        component_id = str(local_target.get("component_id", "") or "")
        anchor_key = self._anchor_key(level_number=state.level_number, component=local_target)
        return bool(
            (credit_component_id and component_id and credit_component_id == component_id)
            or (credit_anchor_key and anchor_key and credit_anchor_key == anchor_key)
        )

    def _consume_post_final_shared_continuation_target_psa_credit(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        credit = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        if not credit:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        credit["consumed_turn"] = effective_step_index
        self.last_post_final_shared_continuation_target_psa_credit = None
        self.last_post_final_shared_continuation_target_psa_credit_consumed = True
        self.post_final_shared_continuation_target_psa_credit_consume_count += 1

    def _refresh_post_final_shared_continuation_target_psa_credit(
        self,
        *,
        state: ECAState,
    ) -> None:
        credit = dict(self.last_post_final_shared_continuation_target_psa_credit or {})
        if not credit:
            return
        if int(credit.get("level_idx", state.level_number) or state.level_number) != int(state.level_number):
            self._expire_post_final_shared_continuation_target_psa_credit(
                step_index=int(state.step_index),
            )
            return
        expires_turn = int(credit.get("expires_turn", -1) or -1)
        if expires_turn >= 0 and int(state.step_index) > expires_turn:
            self._expire_post_final_shared_continuation_target_psa_credit(
                step_index=int(state.step_index),
            )

    def _refresh_post_final_shared_continuation_ticket(
        self,
        *,
        state: ECAState,
    ) -> None:
        ticket = dict(self.last_post_final_shared_continuation_ticket or {})
        if not ticket:
            return
        if int(ticket.get("level_idx", state.level_number) or state.level_number) != int(state.level_number):
            self._expire_post_final_shared_continuation_ticket(
                reason="level_changed",
                step_index=int(state.step_index),
            )
            return
        expires_turn = int(ticket.get("expires_turn", -1) or -1)
        if expires_turn >= 0 and int(state.step_index) > expires_turn:
            self._expire_post_final_shared_continuation_ticket(
                reason="ttl_expired",
                step_index=int(state.step_index),
            )
            return
        component_id = str(ticket.get("component_id", "") or "")
        anchor_key = str(ticket.get("anchor_key", "") or "")
        if (
            (component_id and component_id in self.target_blacklist)
            or (anchor_key and anchor_key in self.target_anchor_blacklist)
        ):
            blocked_grace_reason = self._post_final_shared_continuation_ticket_blocked_grace_reason(
                state=state,
            )
            if blocked_grace_reason:
                ticket["blocked_grace_used"] = True
                ticket["blocked_grace_until"] = int(state.step_index) + self.TARGET_POST_FINAL_SHARED_CONTINUATION_BLOCKED_GRACE_STEPS
                ticket["blocked_grace_reason"] = blocked_grace_reason
                self.last_post_final_shared_continuation_ticket = ticket
                self._record_post_final_shared_continuation_ticket_blocked_grace(
                    reason=blocked_grace_reason,
                )
                return
            self._expire_post_final_shared_continuation_ticket(
                reason="target_blocked",
                step_index=int(state.step_index),
            )

    def _reset_protected_hedge_visibility_hysteresis(self) -> None:
        self.protected_hedge_last_supported_turn = -1
        self.protected_hedge_last_visible_turn = -1
        self.protected_hedge_visibility_grace_until = -1
        self.protected_hedge_visibility_anchor_key = ""
        self.protected_hedge_visibility_step_index = -1
        self.protected_hedge_hard_contradiction_seen = False

    def _reassert_protected_hedge_visibility_hysteresis(
        self,
        *,
        contract: dict[str, Any] | None,
        step_index: int | None = None,
    ) -> None:
        item = dict(contract or {})
        if not item:
            return
        effective_step_index = int(
            step_index
            if step_index is not None
            else (
                self.protected_hedge_visibility_step_index
                if self.protected_hedge_visibility_step_index >= 0
                else (self.last_state.step_index if self.last_state is not None else -1)
            )
        )
        anchor_key = self._protected_hedge_contract_key(item)
        if anchor_key:
            self.protected_hedge_visibility_anchor_key = anchor_key
        self.protected_hedge_visibility_step_index = effective_step_index
        self.protected_hedge_last_visible_turn = max(
            int(self.protected_hedge_last_visible_turn or -1),
            effective_step_index,
        )
        if self._protected_hedge_contract_raw_visible(item):
            self.protected_hedge_last_supported_turn = max(
                int(self.protected_hedge_last_supported_turn or -1),
                effective_step_index,
            )
        self.protected_hedge_visibility_grace_until = max(
            int(self.protected_hedge_visibility_grace_until or -1),
            effective_step_index + self.TARGET_PROTECTED_HEDGE_VISIBILITY_GRACE_STEPS,
        )
        self.protected_hedge_hard_contradiction_seen = False
        self.last_protected_hedge_visible = True

    def _clear_protected_hedge_visibility_hysteresis(
        self,
        *,
        step_index: int | None = None,
        hard_contradiction: bool = False,
    ) -> None:
        self.last_protected_hedge_visible = False
        self.protected_hedge_visibility_step_index = int(
            step_index if step_index is not None else self.protected_hedge_visibility_step_index
        )
        self.protected_hedge_visibility_grace_until = -1
        self.protected_hedge_hard_contradiction_seen = bool(hard_contradiction)

    def _protected_hedge_anchor_cooldown_grace_active(
        self,
        contract: dict[str, Any] | None = None,
        *,
        step_index: int | None = None,
    ) -> bool:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        if not item:
            return False
        anchor_key = str(item.get("anchor_key", "") or "")
        if not anchor_key or anchor_key not in self.target_anchor_blacklist:
            return False
        current_step = int(
            step_index
            if step_index is not None
            else (
                self.protected_hedge_visibility_step_index
                if self.protected_hedge_visibility_step_index >= 0
                else (self.last_state.step_index if self.last_state is not None else -1)
            )
        )
        grace_until = int(item.get("anchor_cooldown_grace_until", -1) or -1)
        return bool(grace_until >= current_step)

    def _protected_hedge_anchor_cooldown_grace_eligible(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
    ) -> bool:
        item = dict(contract or {})
        if not item:
            return False
        anchor_key = str(item.get("anchor_key", "") or "")
        if not anchor_key or anchor_key not in self.target_anchor_blacklist:
            return False
        claim_state = self._protected_hedge_runtime_claim_state(item)
        shared_active = bool(
            claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_SHARED
            and self._post_final_shared_active(item)
        )
        shared_entry_ticket_active = bool(
            shared_active
            and self._post_final_shared_entry_ticket_active(
                contract=item,
                step_index=int(state.step_index),
            )
        )
        if shared_active:
            if bool(item.get("post_final_shared_anchor_cooldown_grace_used", False)) and not shared_entry_ticket_active:
                return False
            if self.current_post_final_shared_first_visible_step_seen:
                return False
        elif bool(item.get("anchor_cooldown_grace_used", False)):
            return False
        if claim_state not in {
            self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED,
            self.PROTECTED_HEDGE_CLAIM_STATE_RECLAIMABLE,
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD,
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD,
            self.PROTECTED_HEDGE_CLAIM_STATE_SHARED,
        }:
            return False
        if (
            claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD
            and bool(item.get("post_final_reclaim_hold_runtime_packet_used", False))
        ):
            return False
        if not self._protected_hedge_contract_active(item):
            return False
        if not shared_entry_ticket_active and not (
            self._protected_hedge_contract_raw_visible(item)
            or self.last_protected_hedge_visible
            or int(self.protected_hedge_last_visible_turn) >= int(state.step_index) - 1
        ):
            return False
        if self.protected_hedge_hard_contradiction_seen:
            return False
        return True

    def _apply_protected_hedge_anchor_cooldown_grace(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
    ) -> dict[str, Any] | None:
        item = dict(contract or {})
        if not item:
            return None
        if not self._protected_hedge_anchor_cooldown_grace_eligible(contract=item, state=state):
            return None
        grace_until = max(
            int(item.get("anchor_cooldown_grace_until", -1) or -1),
            int(state.step_index) + self.TARGET_PROTECTED_HEDGE_ANCHOR_COOLDOWN_GRACE_STEPS,
        )
        item["anchor_cooldown_grace_until"] = grace_until
        item["anchor_cooldown_grace_used"] = True
        claim_state = self._protected_hedge_runtime_claim_state(item)
        if claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_SHARED and self._post_final_shared_active(item):
            if self._post_final_shared_entry_ticket_active(
                contract=item,
                step_index=int(state.step_index),
            ):
                item["post_final_shared_entry_ticket_used"] = True
                self.last_post_final_shared_entry_ticket_consumed = True
                self.post_final_shared_entry_ticket_consume_count += 1
            item["post_final_shared_anchor_cooldown_grace_used"] = True
            item["anchor_cooldown_grace_reason"] = (
                "post_final_shared_entry_ticket"
                if bool(item.get("post_final_shared_entry_ticket_used", False))
                else "post_final_shared_active"
            )
            self.last_post_final_shared_anchor_cooldown_grace_applied = True
            self.post_final_shared_anchor_cooldown_grace_applied_count += 1
        elif claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD:
            item["anchor_cooldown_grace_reason"] = "post_final_reclaim_hold_active"
        else:
            item["anchor_cooldown_grace_reason"] = "runtime_claim_active"
        self.last_protected_hedge_anchor_cooldown_grace_applied = True
        self.protected_hedge_anchor_cooldown_grace_applied_count += 1
        self.last_protected_hedge_contract = item
        return item

    def _protected_hedge_state(self, contract: dict[str, Any] | None = None) -> str:
        return str((contract if contract is not None else self.last_protected_hedge_contract or {}).get("state", "") or "")

    def _protected_hedge_contract_key(self, contract: dict[str, Any] | None = None) -> str:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        return str(item.get("anchor_key", "") or item.get("component_id", "") or "")

    def _protected_hedge_contract_active(self, contract: dict[str, Any] | None = None) -> bool:
        return self._protected_hedge_state(contract) in {
            self.PROTECTED_HEDGE_STATE_ARMED_THIS_TURN,
            self.PROTECTED_HEDGE_STATE_VISIBLE,
            self.PROTECTED_HEDGE_STATE_PINNED,
            self.PROTECTED_HEDGE_STATE_PROBED_ONCE,
        }

    def _protected_hedge_contract_raw_visible(self, contract: dict[str, Any] | None = None) -> bool:
        return self._protected_hedge_state(contract) in {
            self.PROTECTED_HEDGE_STATE_VISIBLE,
            self.PROTECTED_HEDGE_STATE_PINNED,
            self.PROTECTED_HEDGE_STATE_PROBED_ONCE,
        }

    def _protected_hedge_visibility_hard_contradiction(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState | None,
    ) -> bool:
        item = contract or {}
        if not item:
            return True
        if state is not None and int(item.get("level_idx", state.level_number) or state.level_number) != int(
            state.level_number
        ):
            return True
        contract_state = self._protected_hedge_state(item)
        if contract_state in {
            self.PROTECTED_HEDGE_STATE_CONSUMED,
            self.PROTECTED_HEDGE_STATE_INVALIDATED,
        }:
            return True
        anchor_key = str(item.get("anchor_key", "") or "")
        if (
            anchor_key
            and anchor_key in self.target_anchor_blacklist
            and not self._protected_hedge_anchor_cooldown_grace_active(item, step_index=int(state.step_index) if state is not None else None)
        ):
            return True
        return False

    def _refresh_protected_hedge_visibility_hysteresis(self, *, state: ECAState) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        self.protected_hedge_visibility_step_index = int(state.step_index)
        if not contract:
            self.last_protected_hedge_visible = False
            self.protected_hedge_hard_contradiction_seen = False
            return
        anchor_key = self._protected_hedge_contract_key(contract)
        raw_visible = bool(self._protected_hedge_contract_raw_visible(contract))
        if raw_visible:
            self.protected_hedge_last_supported_turn = int(state.step_index)
            self.protected_hedge_last_visible_turn = int(state.step_index)
            self.protected_hedge_visibility_grace_until = (
                int(state.step_index) + self.TARGET_PROTECTED_HEDGE_VISIBILITY_GRACE_STEPS
            )
            self.protected_hedge_visibility_anchor_key = anchor_key
            self.protected_hedge_hard_contradiction_seen = False
            self.last_protected_hedge_visible = True
            return
        if self._protected_hedge_visibility_hard_contradiction(contract=contract, state=state):
            self._clear_protected_hedge_visibility_hysteresis(
                step_index=int(state.step_index),
                hard_contradiction=True,
            )
            return
        within_grace = bool(
            self._protected_hedge_contract_active(contract)
            and anchor_key
            and anchor_key == self.protected_hedge_visibility_anchor_key
            and self.protected_hedge_visibility_grace_until >= int(state.step_index)
        )
        if within_grace:
            self.last_protected_hedge_visible = True
            self.last_protected_hedge_visibility_grace_applied = True
            self.protected_hedge_hard_contradiction_seen = False
            return
        self.last_protected_hedge_visible = False
        self.protected_hedge_hard_contradiction_seen = False

    def _protected_hedge_contract_visible(self, contract: dict[str, Any] | None = None) -> bool:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        if not item:
            return False
        if self._protected_hedge_contract_raw_visible(item):
            return True
        if self.protected_hedge_hard_contradiction_seen:
            return False
        if not self._protected_hedge_contract_active(item):
            return False
        anchor_key = self._protected_hedge_contract_key(item)
        if not anchor_key or anchor_key != self.protected_hedge_visibility_anchor_key:
            return False
        current_step = int(self.protected_hedge_visibility_step_index)
        if current_step < 0:
            return False
        return bool(self.protected_hedge_visibility_grace_until >= current_step)

    def _protected_hedge_runtime_claim_state(self, contract: dict[str, Any] | None = None) -> str:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        if not item:
            return ""
        if not self._protected_hedge_contract_active(item):
            return str(item.get("runtime_claim_state", "") or self.PROTECTED_HEDGE_CLAIM_STATE_EXHAUSTED)
        claim_state = str(item.get("runtime_claim_state", "") or "")
        if claim_state:
            return claim_state
        runtime_probe_budget = max(0, int(item.get("runtime_probe_budget", 1) or 0))
        if runtime_probe_budget > 0:
            return self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED
        return self.PROTECTED_HEDGE_CLAIM_STATE_SHARED

    def _protected_hedge_runtime_claim_active(self, contract: dict[str, Any] | None = None) -> bool:
        return self._protected_hedge_runtime_claim_state(contract) in {
            self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED,
            self.PROTECTED_HEDGE_CLAIM_STATE_RECLAIMABLE,
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD,
            self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE,
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD,
        }

    def _protected_hedge_runtime_reclaim_used(self, contract: dict[str, Any] | None = None) -> bool:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        return bool(item.get("runtime_reclaim_used", False))

    def _protected_hedge_claimed_visible_rearm_block_reason(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        same_contract: bool,
        no_change_streak: int,
        current_target_psa_dead_end: bool,
        current_target_lifecycle_state: str,
    ) -> str:
        item = dict(contract or {})
        if not item or not self._protected_hedge_contract_active(item):
            return "inactive_contract"
        if self._protected_hedge_runtime_claim_state(item) != self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED:
            return "wrong_claim_state"
        if self._post_final_shared_active(item):
            return "post_final_shared_active"
        if self._protected_hedge_runtime_reclaim_used(item):
            return "reclaim_already_used"
        if self.protected_hedge_hard_contradiction_seen:
            return "hard_contradiction_seen"
        effective_step_index = int(state.step_index)
        min_steps = int(self.TARGET_PROTECTED_HEDGE_CLAIMED_VISIBLE_REARM_MIN_STEPS or 0)
        claim_rearm_reason = str(item.get("runtime_claim_rearm_reason", "") or "")
        if same_contract and claim_rearm_reason in {
            "selected_target_promotion",
            "claimed_visible_terminalizing",
        }:
            min_steps = max(1, min_steps - 1)
        visible_from_step_idx = int(item.get("visible_from_step_idx", -1) or -1)
        pinned_from_step_idx = int(item.get("pinned_from_step_idx", -1) or -1)
        claim_transition_step_idx = int(
            item.get("runtime_claim_last_transition_step_idx", -1) or -1
        )
        if claim_transition_step_idx < 0:
            inferred_claim_age = max(
                (
                    effective_step_index - visible_from_step_idx
                    if visible_from_step_idx >= 0
                    else -1
                ),
                (
                    effective_step_index - pinned_from_step_idx
                    if pinned_from_step_idx >= 0
                    else -1
                ),
            )
            if inferred_claim_age < min_steps:
                return "claim_transition_missing"
            claim_age = inferred_claim_age
        else:
            claim_age = effective_step_index - claim_transition_step_idx
        target_terminalizing = (not same_contract) and (
            bool(current_target_psa_dead_end)
            or current_target_lifecycle_state in {
                self.TARGET_LIFECYCLE_DEAD_TERMINAL,
                self.TARGET_LIFECYCLE_DEAD_COOLDOWN,
                self.TARGET_LIFECYCLE_DEAD_REVISIT,
                self.TARGET_LIFECYCLE_FOLLOWUP_PACKET_USED,
            }
        )
        armed_terminalizing_visibility_bridge = bool(
            target_terminalizing
            and self._protected_hedge_state(item) == self.PROTECTED_HEDGE_STATE_ARMED_THIS_TURN
            and not self.protected_hedge_hard_contradiction_seen
        )
        if not bool(
            self._protected_hedge_contract_raw_visible(item)
            or self._protected_hedge_contract_visible(item)
            or self.last_protected_hedge_visible
            or armed_terminalizing_visibility_bridge
        ):
            return "protected_hedge_not_visible"
        if same_contract and claim_rearm_reason in {
            "",
            "claimed_visible_terminalizing",
        }:
            return ""
        if visible_from_step_idx >= 0 and effective_step_index - visible_from_step_idx >= min_steps:
            return ""
        if pinned_from_step_idx >= 0 and effective_step_index - pinned_from_step_idx >= max(1, min_steps - 1):
            return ""
        if bool(
            int(self.protected_hedge_last_visible_turn or -1) >= effective_step_index - 1
            and claim_age >= min_steps + 1
        ):
            return ""
        if target_terminalizing:
            return ""
        if claim_age < min_steps:
            return "claim_too_fresh"
        return "visible_age_too_short"

    def _record_protected_hedge_claimed_rearm_block_reason(self, reason: str) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        self.protected_hedge_claimed_rearm_block_reason_histogram[normalized_reason] = int(
            self.protected_hedge_claimed_rearm_block_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1
        self.last_protected_hedge_claimed_rearm_block_reason = normalized_reason

    def _record_protected_hedge_claimed_rearm_block_context(
        self,
        *,
        reason: str,
        same_contract: bool,
        claim_rearm_reason: str,
        current_target_lifecycle_state: str,
        current_target_psa_dead_end: bool,
    ) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        context = (
            f"{normalized_reason}"
            f"|same_contract={1 if same_contract else 0}"
            f"|claim_rearm_reason={str(claim_rearm_reason or '').strip() or 'none'}"
            f"|lifecycle={str(current_target_lifecycle_state or '').strip() or 'none'}"
            f"|psa_dead_end={1 if bool(current_target_psa_dead_end) else 0}"
        )
        self.protected_hedge_claimed_rearm_block_context_histogram[context] = int(
            self.protected_hedge_claimed_rearm_block_context_histogram.get(context, 0) or 0
        ) + 1
        self.last_protected_hedge_claimed_rearm_block_context = context

    def _protected_hedge_claimed_visible_rearm_ready(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        same_contract: bool,
        no_change_streak: int,
        current_target_psa_dead_end: bool,
        current_target_lifecycle_state: str,
    ) -> bool:
        return not bool(
            self._protected_hedge_claimed_visible_rearm_block_reason(
                contract=contract,
                state=state,
                same_contract=same_contract,
                no_change_streak=no_change_streak,
                current_target_psa_dead_end=current_target_psa_dead_end,
                current_target_lifecycle_state=current_target_lifecycle_state,
            )
        )

    def _last_selected_target_summary_object(self) -> SelectedTargetSummary | None:
        item = dict(self.last_selected_target_summary or {})
        if not item:
            return None
        return SelectedTargetSummary(
            candidate_id=str(item.get("candidate_id", "") or ""),
            anchor_key=str(item.get("anchor_key", "") or ""),
            source=str(item.get("source", "") or ""),
            admission_score=float(item.get("admission_score", 0.0) or 0.0),
            suggested_probe_reason=str(item.get("suggested_probe_reason", "") or ""),
            click_budget=int(item.get("click_budget", 0) or 0),
            move_probe_budget=int(item.get("move_probe_budget", 0) or 0),
            rotate_cost=float(item.get("rotate_cost", 0.0) or 0.0),
            confidence=str(item.get("confidence", "") or ""),
            runtime_probe_ok=bool(item.get("runtime_probe_ok", False)),
            component_id=str(item.get("component_id", "") or ""),
            transfer_hint_bonus=float(item.get("transfer_hint_bonus", 0.0) or 0.0),
            second_chance_kind=str(item.get("second_chance_kind", "") or ""),
            recovery_after_state=str(item.get("recovery_after_state", "") or ""),
            recovery_after_reason=str(item.get("recovery_after_reason", "") or ""),
            transition_model_candidate_family=str(item.get("transition_model_candidate_family", "") or ""),
            transition_model_backoff_level=str(item.get("transition_model_backoff_level", "") or ""),
            transition_model_support=int(item.get("transition_model_support", 0) or 0),
            transition_model_p_contract=float(item.get("transition_model_p_contract", 0.0) or 0.0),
            transition_model_p_frontier=float(item.get("transition_model_p_frontier", 0.0) or 0.0),
            transition_model_p_turnover=float(item.get("transition_model_p_turnover", 0.0) or 0.0),
            transition_model_p_dead_churn=float(item.get("transition_model_p_dead_churn", 0.0) or 0.0),
            transition_model_p_slip=float(item.get("transition_model_p_slip", 0.0) or 0.0),
            transition_model_quality_gain=float(item.get("transition_model_quality_gain", 0.0) or 0.0),
            transition_model_predicted_anxiety=float(item.get("transition_model_predicted_anxiety", 0.0) or 0.0),
        )

    def _selected_target_summary_effectively_empty(
        self,
        selected_target_summary: SelectedTargetSummary | None,
    ) -> bool:
        if selected_target_summary is None:
            return True
        return not bool(
            str(selected_target_summary.component_id or "")
            or str(selected_target_summary.candidate_id or "")
        )

    def _provisional_target_bootstrap_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        item = dict(self.last_provisional_target_bootstrap or {})
        if not item:
            return False
        current_step = (
            int(step_index)
            if step_index is not None
            else int(self.last_state.step_index) if self.last_state is not None else -10_000
        )
        expires_at = int(item.get("expires_at", current_step) or current_step)
        return current_step <= expires_at

    def _refresh_provisional_target_bootstrap(
        self,
        *,
        step_index: int,
    ) -> None:
        self.last_provisional_target_bootstrap_issued = False
        self.last_provisional_target_bootstrap_expired = False
        self.last_provisional_target_bootstrap_ttl_remaining = 0
        item = dict(self.last_provisional_target_bootstrap or {})
        if not item:
            return
        if not self._provisional_target_bootstrap_active(step_index=step_index):
            self.provisional_target_bootstrap_expire_count += 1
            self.last_provisional_target_bootstrap_expired = True
            current_summary = dict(self.last_selected_target_summary or {})
            if (
                current_summary
                and str(current_summary.get("source", "") or "") == "provisional_base_pool"
                and (
                    str(current_summary.get("component_id", "") or "")
                    == str(item.get("component_id", "") or "")
                    or str(current_summary.get("anchor_key", "") or "")
                    == str(item.get("anchor_key", "") or "")
                )
            ):
                self.last_selected_target_summary = None
            self.last_provisional_target_bootstrap = None
            return
        self.last_provisional_target_bootstrap_ttl_remaining = max(
            0,
            int(item.get("expires_at", step_index) or step_index) - int(step_index),
        )

    def _build_provisional_target_summary_from_base_candidate(
        self,
        *,
        state: ECAState,
        candidate: Any,
    ) -> SelectedTargetSummary | None:
        candidate_get = (
            candidate.get
            if isinstance(candidate, dict)
            else lambda key, default=None: getattr(candidate, key, default)
        )
        component_id = str(
            candidate_get("component_id", "") or candidate_get("id", "") or ""
        ).strip()
        if not component_id:
            return None
        anchor_key = str(candidate_get("anchor_key", "") or "").strip()
        if not anchor_key:
            center_row = int(
                candidate_get("center_row", candidate_get("row", 0)) or 0
            )
            center_col = int(
                candidate_get("center_col", candidate_get("col", 0)) or 0
            )
            anchor_key = f"{int(state.level_number)}||{center_row}||{center_col}"
        source = str(candidate_get("source", "") or "base_pool").strip() or "base_pool"
        family = str(
            candidate_get("family", "") or candidate_get("action_family", "") or ""
        ).strip()
        base_score = float(
            candidate_get("base_score", candidate_get("score", 0.0)) or 0.0
        )
        candidate_id = f"{int(state.level_number)}:{component_id}:{source}"
        return SelectedTargetSummary(
            candidate_id=candidate_id,
            anchor_key=anchor_key,
            source="provisional_base_pool",
            admission_score=base_score,
            suggested_probe_reason="provisional_target_bootstrap",
            click_budget=1 if family == "click" else 0,
            move_probe_budget=1 if family == "move" else 0,
            rotate_cost=0.0,
            confidence="low",
            runtime_probe_ok=False,
            component_id=component_id,
            transfer_hint_bonus=0.0,
            second_chance_kind="provisional_target_bootstrap",
            recovery_after_state="",
            recovery_after_reason="",
        )

    def _build_selected_target_summary_from_local_controller_candidate(
        self,
        *,
        state: ECAState,
        candidate: Any,
        resolution_source: str = "",
    ) -> SelectedTargetSummary | None:
        component_id = str(getattr(candidate, "component_id", "") or "").strip()
        action_family = str(getattr(candidate, "action_family", "") or "").strip()
        if not component_id:
            return None
        anchor_key = str(getattr(candidate, "anchor_key", "") or "").strip()
        center_row = int(getattr(candidate, "center_row", 0) or 0)
        center_col = int(getattr(candidate, "center_col", 0) or 0)
        source = str(getattr(candidate, "source", "") or "local_controller").strip() or "local_controller"
        if (not anchor_key or not (center_row or center_col)) and self.last_candidate_pool:
            for entry in list(self.last_candidate_pool or []):
                entry_component_id = str(
                    entry.get("component_id", "") or entry.get("id", "") or ""
                ).strip()
                if entry_component_id != component_id:
                    continue
                anchor_key = anchor_key or str(entry.get("anchor_key", "") or "").strip()
                center_row = center_row or int(
                    entry.get("center_row", entry.get("row", 0)) or 0
                )
                center_col = center_col or int(
                    entry.get("center_col", entry.get("col", 0)) or 0
                )
                source = source or str(entry.get("source", "") or "").strip()
                if not action_family:
                    action_family = str(
                        entry.get("family", "") or entry.get("action_family", "") or ""
                    ).strip()
                break
        if (not anchor_key or not (center_row or center_col)):
            base_pool = getattr(self, "_last_base_pool", None)
            for item in list(getattr(base_pool, "candidates", None) or []):
                if str(getattr(item, "component_id", "") or "").strip() != component_id:
                    continue
                anchor_key = anchor_key or str(getattr(item, "anchor_key", "") or "").strip()
                center_row = center_row or int(getattr(item, "center_row", 0) or 0)
                center_col = center_col or int(getattr(item, "center_col", 0) or 0)
                source = source or str(getattr(item, "source", "") or "").strip()
                if not action_family:
                    action_family = str(getattr(item, "family", "") or "").strip()
                break
        if not anchor_key:
            anchor_key = f"{int(state.level_number)}||{center_row}||{center_col}"
        candidate_id = f"{int(state.level_number)}:{component_id}:{source}"
        confidence = "medium" if str(resolution_source or "").startswith("ir_") else "low"
        return SelectedTargetSummary(
            candidate_id=candidate_id,
            anchor_key=anchor_key,
            source=source,
            admission_score=float(
                getattr(candidate, "base_admission_score", 0.0)
                or getattr(candidate, "resolver_score", 0.0)
                or 0.0
            ),
            suggested_probe_reason=str(resolution_source or "local_controller"),
            click_budget=1 if action_family == "click" else 0,
            move_probe_budget=1 if action_family == "move" else 0,
            rotate_cost=0.0,
            confidence=confidence,
            runtime_probe_ok=False,
            component_id=component_id,
            transfer_hint_bonus=0.0,
            second_chance_kind="",
            recovery_after_state="",
            recovery_after_reason="",
            transition_model_candidate_family=action_family,
        )

    @staticmethod
    def _copy_rule_discovery_candidate_metadata(payload: dict[str, Any], candidate: Any) -> None:
        for key in (
            "stage",
            "closure_status",
            "hypothesis_id",
            "hypothesis_kind",
            "linked_effect_id",
            "window_id",
            "continuation_kind",
        ):
            value = str(getattr(candidate, key, "") or "").strip()
            if value:
                payload[key] = value

    def _sync_local_controller_selected_target(
        self,
        *,
        state: ECAState,
        result: Any,
    ) -> None:
        if result is None:
            return
        selected = getattr(result, "selected_target", None)
        if selected is None:
            return
        resolution_source = str(
            getattr(getattr(result, "resolution", None), "resolution_source", "")
            or ""
        )
        summary = self._build_selected_target_summary_from_local_controller_candidate(
            state=state,
            candidate=selected,
            resolution_source=resolution_source,
        )
        if summary is None:
            return
        current_summary = self._last_selected_target_summary_object()
        current_component_id = str(getattr(current_summary, "component_id", "") or "")
        should_overwrite = self._selected_target_summary_effectively_empty(current_summary)
        if not should_overwrite and current_component_id != str(summary.component_id or ""):
            should_overwrite = True
        if not should_overwrite and resolution_source in {
            "ir_stale_retarget",
            "ir_low_gain_div",
            "ir_saturation_relief",
            "closed_rule_one_shot",
            "stabilize_verify_one_shot",
        }:
            should_overwrite = True
        if not should_overwrite and current_component_id == str(summary.component_id or ""):
            payload = dict(self.last_selected_target_summary or {})
            action_family = str(getattr(selected, "action_family", "") or "").strip().lower()
            payload["component_id"] = str(summary.component_id or payload.get("component_id", "") or "")
            payload["anchor_key"] = str(summary.anchor_key or payload.get("anchor_key", "") or "")
            payload["candidate_id"] = str(summary.candidate_id or payload.get("candidate_id", "") or "")
            self._copy_rule_discovery_candidate_metadata(payload, selected)
            if action_family in {"click", "move"}:
                payload["action_family"] = action_family
                payload["transition_model_candidate_family"] = action_family
                payload["click_budget"] = 1 if action_family == "click" else 0
                payload["move_probe_budget"] = 1 if action_family == "move" else 0
                payload["runtime_probe_ok"] = False
            payload["local_controller_resolution_source"] = resolution_source
            self.last_selected_target_summary = payload
            target_label = str(summary.component_id or "")
            center_row = int(getattr(selected, "center_row", 0) or 0)
            center_col = int(getattr(selected, "center_col", 0) or 0)
            if center_row or center_col:
                target_label = f"{target_label} at {{'row': {center_row}, 'col': {center_col}}}"
            self.last_effective_local_target_summary = target_label
            self.last_effective_local_contract_source = (
                self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_SELECTED_TARGET
            )
            self.last_effective_local_contract_component_id = str(summary.component_id or "")
            self.last_effective_local_contract_anchor = str(summary.anchor_key or "")
            self.plan_contract.local_target = target_label
            return
        if not should_overwrite:
            return
        payload = summary.to_dict()
        self._copy_rule_discovery_candidate_metadata(payload, selected)
        payload["action_family"] = str(getattr(selected, "action_family", "") or "")
        payload["local_controller_resolution_source"] = resolution_source
        self.last_selected_target_summary = payload
        target_label = str(summary.component_id or "")
        center_row = int(getattr(selected, "center_row", 0) or 0)
        center_col = int(getattr(selected, "center_col", 0) or 0)
        if center_row or center_col:
            target_label = f"{target_label} at {{'row': {center_row}, 'col': {center_col}}}"
        self.last_effective_local_target_summary = target_label
        self.last_effective_local_contract_source = (
            self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_SELECTED_TARGET
        )
        self.last_effective_local_contract_component_id = str(summary.component_id or "")
        self.last_effective_local_contract_anchor = str(summary.anchor_key or "")
        self.plan_contract.local_target = target_label

    def _local_target_from_selected_target_summary(
        self,
        *,
        state: ECAState,
        summary: SelectedTargetSummary | None,
    ) -> dict[str, Any]:
        if summary is None:
            return {}
        component_id = str(summary.component_id or summary.candidate_id or "").strip()
        anchor_key = str(summary.anchor_key or "").strip()
        parsed_anchor = self._parse_anchor_key(anchor_key)
        center: dict[str, int] = {}
        if parsed_anchor is not None:
            _, row, col = parsed_anchor
            center = {"row": int(row), "col": int(col)}
        if not component_id and not center:
            return {}
        return {
            "component_id": component_id,
            "anchor_key": anchor_key,
            "center": center,
            "bbox": {},
            "level": int(state.level_number),
        }

    def _refresh_local_controller_followup_lifecycle(self, *, state: ECAState) -> None:
        summary = self._last_selected_target_summary_object()
        local_target = self._local_target_from_selected_target_summary(
            state=state,
            summary=summary,
        )
        if not local_target:
            return
        lifecycle_state, lifecycle_reason = self._current_target_lifecycle(
            state=state,
            local_target=local_target,
            fresh_target_after_rotation=False,
            revisiting_dead_anchor=False,
            current_target_psa_dead_end=bool(self.last_current_target_psa_dead_end),
            current_target_psa_state=str(self.last_current_target_psa_state or ""),
        )
        self.last_target_lifecycle_state = lifecycle_state
        self.last_target_lifecycle_reason = lifecycle_reason

    def _match_focus_component_for_provisional_target(
        self,
        *,
        focus_components: list[dict[str, Any]],
        summary: SelectedTargetSummary | None,
    ) -> dict[str, Any]:
        if summary is None:
            return {}
        component_id = str(summary.component_id or "")
        anchor_key = str(summary.anchor_key or "")
        for component in focus_components:
            if not component:
                continue
            if component_id and str(component.get("component_id", "") or "") == component_id:
                return component
            component_anchor = str(component.get("anchor_key", "") or "")
            if not component_anchor:
                component_anchor = self._anchor_key(
                    level_number=int(self.last_state.level_number) if self.last_state is not None else 0,
                    component=component,
                )
            if anchor_key and component_anchor == anchor_key:
                return component
        return {}

    def _maybe_apply_provisional_target_bootstrap(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        local_target: dict[str, Any],
        focus_components: list[dict[str, Any]],
    ) -> tuple[SelectedTargetSummary | None, dict[str, Any]]:
        selected_target_effectively_empty = self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        )
        if selected_target_summary is not None and not selected_target_effectively_empty:
            if str(selected_target_summary.source or "") != "provisional_base_pool":
                self.last_provisional_target_bootstrap = None
            return selected_target_summary, local_target
        if selected_target_effectively_empty:
            selected_target_summary = None

        active_item = dict(self.last_provisional_target_bootstrap or {})
        if active_item and self._provisional_target_bootstrap_active(step_index=int(state.step_index)):
            summary = self._last_selected_target_summary_object()
            if summary is not None and str(summary.source or "") == "provisional_base_pool":
                matched_component = self._match_focus_component_for_provisional_target(
                    focus_components=focus_components,
                    summary=summary,
                )
                return summary, matched_component or local_target

        health = getattr(getattr(self, "_last_target_health_result", None), "health", None)
        if str(getattr(health, "value", health) or "").lower() != "empty":
            return selected_target_summary, local_target

        base_pool = getattr(self, "_last_base_pool", None)
        candidates = list(getattr(base_pool, "candidates", None) or [])
        if not candidates:
            candidates = []

        def _candidate_like_score(item: Any) -> float:
            item_get = (
                item.get
                if isinstance(item, dict)
                else lambda key, default=None: getattr(item, key, default)
            )
            return (
                float(item_get("base_score", item_get("score", 0.0)) or 0.0)
                + (0.05 if bool(item_get("recent_live", False)) else 0.0)
                + (0.03 if bool(item_get("is_hedge", False)) else 0.0)
                - (0.10 if str(item_get("reject_reason", "") or item_get("rejected_reason", "") or "") else 0.0)
            )

        summary: SelectedTargetSummary | None = None
        ranked_candidates = sorted(candidates, key=_candidate_like_score, reverse=True)
        if ranked_candidates:
            summary = self._build_provisional_target_summary_from_base_candidate(
                state=state,
                candidate=ranked_candidates[0],
            )
        if summary is None:
            raw_candidates = list(self.last_candidate_pool or [])
            ranked_raw_candidates = sorted(
                raw_candidates,
                key=_candidate_like_score,
                reverse=True,
            )
            if ranked_raw_candidates:
                summary = self._build_provisional_target_summary_from_base_candidate(
                    state=state,
                    candidate=ranked_raw_candidates[0],
                )
        if summary is None:
            return selected_target_summary, local_target

        self.last_selected_target_summary = summary.to_dict()
        self.last_provisional_target_bootstrap = {
            "component_id": str(summary.component_id or ""),
            "anchor_key": str(summary.anchor_key or ""),
            "candidate_id": str(summary.candidate_id or ""),
            "source": str(summary.source or ""),
            "issued_step": int(state.step_index),
            "expires_at": int(state.step_index) + int(self.PROVISIONAL_TARGET_BOOTSTRAP_TTL_STEPS),
        }
        self.provisional_target_bootstrap_issue_count += 1
        self.last_provisional_target_bootstrap_issued = True
        self.last_provisional_target_bootstrap_ttl_remaining = int(self.PROVISIONAL_TARGET_BOOTSTRAP_TTL_STEPS)
        matched_component = self._match_focus_component_for_provisional_target(
            focus_components=focus_components,
            summary=summary,
        )
        return summary, matched_component or local_target

    def _protected_hedge_matches_last_effective_local_contract(
        self,
        contract: dict[str, Any] | None = None,
    ) -> bool:
        return self._protected_hedge_matches_local_contract(
            effective_local_contract_source=str(
                self.last_effective_local_contract_source
                or self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_NONE
            ),
            effective_local_contract_component_id=str(
                self.last_effective_local_contract_component_id or ""
            ),
            effective_local_contract_anchor=str(self.last_effective_local_contract_anchor or ""),
            selected_target_summary=self._last_selected_target_summary_object(),
            contract=contract,
        )

    def _protected_hedge_runtime_probe_pending(self, contract: dict[str, Any] | None = None) -> bool:
        return self._protected_hedge_runtime_claim_state(contract) in {
            self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED,
            self.PROTECTED_HEDGE_CLAIM_STATE_RECLAIMABLE,
            self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE,
        }

    def _protected_hedge_runtime_claim_enforces_contract(
        self,
        contract: dict[str, Any] | None = None,
    ) -> bool:
        claim_state = self._protected_hedge_runtime_claim_state(contract)
        if claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_SHARED:
            return self._post_final_shared_recent_rerank_support(contract=contract)
        return claim_state in {
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD,
            self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE,
            self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD,
        }

    def _protected_hedge_successful_reclaim_active(
        self,
        contract: dict[str, Any] | None = None,
    ) -> bool:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        if not item:
            return False
        successful_reclaim_step_idx = item.get("successful_reclaim_step_idx", None)
        if successful_reclaim_step_idx in (None, ""):
            return False
        return int(successful_reclaim_step_idx) >= 0 and (
            self._protected_hedge_runtime_claim_state(item) != self.PROTECTED_HEDGE_CLAIM_STATE_EXHAUSTED
        )

    def _clear_protected_hedge_runtime_aftercare_fields(
        self,
        *,
        contract: dict[str, Any],
        preserve_final_reclaim_used: bool = False,
    ) -> None:
        contract["successful_reclaim_step_idx"] = -1
        contract["successful_reclaim_strength"] = ""
        contract["successful_reclaim_stable_tail_count"] = 0
        contract["successful_reclaim_queue_exhaustion_count"] = 0
        contract["successful_reclaim_exhausted_counted"] = False
        contract["post_reclaim_hold_entered_step_idx"] = -1
        contract["post_reclaim_hold_stable_turn_used"] = False
        contract["post_reclaim_hold_stable_turn_step_idx"] = -1
        contract["post_reclaim_hold_runtime_confirmed"] = False
        contract["post_reclaim_hold_runtime_confirm_step_idx"] = -1
        contract["final_reclaimable_entered_step_idx"] = -1
        contract["final_reclaimable_reason"] = ""
        contract["post_final_reclaim_hold_entered_step_idx"] = -1
        contract["post_final_reclaim_hold_stable_turn_used"] = False
        contract["post_final_reclaim_hold_stable_turn_step_idx"] = -1
        contract["post_final_reclaim_hold_runtime_confirmed"] = False
        contract["post_final_reclaim_hold_runtime_confirm_step_idx"] = -1
        contract["post_final_reclaim_hold_rendered"] = False
        contract["post_final_reclaim_hold_ignore_inherited_terminalizing"] = False
        contract["post_final_reclaim_hold_runtime_packet_pending"] = False
        contract["post_final_reclaim_hold_runtime_packet_used"] = False
        contract["post_final_hold_survived_one_step_counted"] = False
        contract["post_final_hold_forced_packet_offered"] = False
        contract["post_final_hold_runtime_packet_eligible_step_idx"] = -10_000
        contract["post_final_shared_active"] = False
        contract["post_final_shared_entered_step_idx"] = -1
        contract["post_final_shared_entry_forced_packet"] = False
        contract["post_final_shared_forced_rerank_offered"] = False
        contract["post_final_shared_delayed_reclaim_used"] = False
        contract["post_final_shared_anchor_cooldown_grace_used"] = False
        contract["post_final_shared_entry_ticket_expires_turn"] = -1
        contract["post_final_shared_entry_ticket_used"] = False
        contract["post_final_shared_last_rerank_pass_step_idx"] = -10_000
        contract["post_final_shared_queue_exhausted_streak"] = 0
        contract["post_final_shared_last_queue_exhausted_step_idx"] = -10_000
        contract["post_final_shared_same_contract_stable_streak"] = 0
        contract["post_final_shared_last_same_contract_stable_step_idx"] = -10_000
        contract["post_final_shared_last_nonempty_selected_target_step_idx"] = -10_000
        contract["post_final_shared_last_dead_tail_pressure_step_idx"] = -10_000
        contract["post_final_shared_best_live_escape_candidate_count"] = 0
        contract["post_final_shared_best_escape_candidate_score"] = 0.0
        contract["post_final_shared_best_escape_candidate_threshold_gap"] = 0.0
        if not preserve_final_reclaim_used:
            contract["runtime_final_reclaim_used"] = False

    def _record_successful_reclaim_exhaustion(
        self,
        *,
        contract: dict[str, Any],
        step_index: int,
    ) -> None:
        successful_reclaim_step_idx = contract.get("successful_reclaim_step_idx", None)
        if successful_reclaim_step_idx in (None, ""):
            return
        if bool(contract.get("successful_reclaim_exhausted_counted", False)):
            return
        lag = max(0, int(step_index) - int(successful_reclaim_step_idx))
        self.successful_reclaim_to_exhausted_turn_total += lag
        self.successful_reclaim_to_exhausted_turn_count += 1
        contract["successful_reclaim_exhausted_counted"] = True

    def _record_post_reclaim_hold_exit_reason(self, reason: str) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        self.post_reclaim_hold_exit_reason_histogram[normalized_reason] = int(
            self.post_reclaim_hold_exit_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1

    def _record_post_final_reclaim_hold_exit_reason(self, reason: str) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        self.post_final_reclaim_hold_exit_reason_histogram[normalized_reason] = int(
            self.post_final_reclaim_hold_exit_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1
        if normalized_reason.endswith("_to_consume"):
            self.post_final_hold_consume_reason_histogram[normalized_reason] = int(
                self.post_final_hold_consume_reason_histogram.get(normalized_reason, 0) or 0
            ) + 1

    def _post_final_shared_active(self, contract: dict[str, Any] | None = None) -> bool:
        item = contract if contract is not None else dict(self.last_protected_hedge_contract or {})
        if not item or not self._protected_hedge_contract_active(item):
            return False
        if self._protected_hedge_runtime_claim_state(item) != self.PROTECTED_HEDGE_CLAIM_STATE_SHARED:
            return False
        return bool(item.get("post_final_shared_active", False)) and int(
            item.get("post_final_shared_entered_step_idx", -1) or -1
        ) >= 0

    def _post_final_shared_visible(self, contract: dict[str, Any] | None = None) -> bool:
        item = contract if contract is not None else dict(self.last_protected_hedge_contract or {})
        if not self._post_final_shared_active(item):
            return False
        return bool(self.last_protected_hedge_visible or self._protected_hedge_contract_visible(item))

    def _post_final_shared_entry_ticket_active(
        self,
        *,
        contract: dict[str, Any] | None = None,
        step_index: int | None = None,
    ) -> bool:
        item = contract if contract is not None else dict(self.last_protected_hedge_contract or {})
        if not self._post_final_shared_active(item):
            return False
        if self.current_post_final_shared_first_visible_step_seen:
            return False
        if bool(item.get("post_final_shared_entry_ticket_used", False)):
            return False
        effective_step_index = int(
            step_index
            if step_index is not None
            else (self.last_state.step_index if self.last_state is not None else -1)
        )
        expires_turn = int(item.get("post_final_shared_entry_ticket_expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _post_final_shared_recent_rerank_support(
        self,
        *,
        contract: dict[str, Any] | None = None,
        step_index: int | None = None,
    ) -> bool:
        item = contract if contract is not None else dict(self.last_protected_hedge_contract or {})
        if not self._post_final_shared_active(item):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -10_000)
        )
        rerank_step_idx = int(item.get("post_final_shared_last_rerank_pass_step_idx", -10_000) or -10_000)
        if rerank_step_idx < 0:
            return False
        return rerank_step_idx >= (
            effective_step_index - self.TARGET_POST_FINAL_SHARED_RERANK_SUPPORT_WINDOW_STEPS + 1
        )

    def _post_final_shared_first_visible_psa_rearm_ready(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        current_target_psa_dead_end: bool,
        selected_target_empty_with_candidate_pool: bool = False,
    ) -> bool:
        item = dict(contract if contract is not None else self.last_protected_hedge_contract or {})
        if not self._post_final_shared_active(item):
            return False
        if self._post_final_shared_recent_nonempty_selected_target(
            contract=item,
            step_index=int(state.step_index),
        ):
            return False
        if bool(selected_target_summary):
            return False
        if bool(selected_target_empty_with_candidate_pool):
            return False
        if not bool(current_target_psa_dead_end):
            return False
        if bool(item.get("post_final_shared_delayed_reclaim_used", False)):
            return False
        if bool(item.get("post_final_shared_first_visible_psa_rearm_used", False)):
            return False
        if self._post_final_shared_recent_rerank_support(
            contract=item,
            step_index=int(state.step_index),
        ):
            return False
        entered_step_idx = int(item.get("post_final_shared_entered_step_idx", -1) or -1)
        if entered_step_idx < 0:
            return False
        return int(state.step_index) <= entered_step_idx + 1

    def _mark_post_final_shared_nonempty_selected_target(
        self,
        *,
        contract: dict[str, Any] | None,
        step_index: int,
        selected_target_summary: SelectedTargetSummary | None,
    ) -> None:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item or not self._post_final_shared_active(item):
            return
        if selected_target_summary is None:
            return
        if self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        ):
            return
        effective_step_index = int(step_index)
        if int(item.get("post_final_shared_last_nonempty_selected_target_step_idx", -10_000) or -10_000) == effective_step_index:
            return
        item["post_final_shared_last_nonempty_selected_target_step_idx"] = effective_step_index
        self.last_protected_hedge_contract = item
        if contract is not None:
            contract.clear()
            contract.update(item)

    def _post_final_shared_recent_nonempty_selected_target(
        self,
        *,
        contract: dict[str, Any] | None,
        step_index: int,
    ) -> bool:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item or not self._post_final_shared_active(item):
            return False
        last_seen_step_idx = int(
            item.get("post_final_shared_last_nonempty_selected_target_step_idx", -10_000)
            or -10_000
        )
        if last_seen_step_idx < 0:
            return False
        effective_step_index = int(step_index)
        return last_seen_step_idx >= (
            effective_step_index - self.TARGET_POST_FINAL_SHARED_RECENT_NONEMPTY_TARGET_RETAIN_STEPS + 1
        )

    def _post_final_shared_effective_route_summary(
        self,
        *,
        contract: dict[str, Any] | None,
        selected_target_summary: SelectedTargetSummary | None,
        step_index: int,
    ) -> SelectedTargetSummary | None:
        if selected_target_summary is not None and not self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        ):
            return selected_target_summary
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item or not self._post_final_shared_active(item):
            return None
        if not self._post_final_shared_recent_nonempty_selected_target(
            contract=item,
            step_index=int(step_index),
        ):
            return None
        component_id = str(
            item.get("promoted_selected_target_component_id", "")
            or item.get("component_id", "")
            or ""
        ).strip()
        anchor_key = str(
            item.get("promoted_selected_target_anchor", "")
            or item.get("anchor_key", "")
            or self._protected_hedge_contract_key(item)
            or ""
        ).strip()
        if not component_id and not anchor_key:
            return None
        action_family = str(
            item.get("action_family", "")
            or item.get("family", "")
            or item.get("seed_source", "")
            or ""
        ).strip()
        source = str(item.get("source", "") or item.get("seed_source", "") or "protected_hedge").strip()
        return SelectedTargetSummary(
            candidate_id=str(
                item.get("promoted_selected_target_candidate_id", "")
                or f"{int(self.last_state.level_number if self.last_state else 0)}:{component_id}:{source}"
            ),
            anchor_key=anchor_key,
            source=source or "protected_hedge",
            admission_score=float(item.get("admission_score", 0.0) or 0.0),
            suggested_probe_reason="post_final_shared_retained_route",
            click_budget=1 if action_family == "click" else 0,
            move_probe_budget=1 if action_family != "click" else 0,
            rotate_cost=0.0,
            confidence="low",
            runtime_probe_ok=True,
            component_id=component_id,
            transition_model_candidate_family=action_family,
        )

    def _post_final_shared_probe_budget_class(
        self,
        *,
        viability_drop_reason: str = "",
    ) -> str:
        normalized_reason = str(viability_drop_reason or "").strip()
        if normalized_reason == "target_move_probe_exhausted":
            return "move"
        if normalized_reason == "target_family_probe_exhausted":
            return "family"
        if normalized_reason == "target_click_probe_exhausted":
            return "click"
        if normalized_reason == "fresh_target_minimal_probe_exhausted":
            return "minimal"
        return "none"

    def _selected_target_summary_from_retained_route_anchor(
        self,
    ) -> SelectedTargetSummary | None:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return None
        component_id = str(anchor.get("component_id", "") or "").strip()
        anchor_key = str(anchor.get("anchor_key", "") or "").strip()
        candidate_id = str(anchor.get("candidate_id", "") or "").strip()
        source = str(anchor.get("source", "") or "protected_hedge").strip()
        family = str(anchor.get("source_family", "") or "").strip()
        if not component_id and not candidate_id:
            return None
        return SelectedTargetSummary(
            candidate_id=(
                candidate_id
                or f"{int(self.last_state.level_number if self.last_state else 0)}:{component_id}:{source}"
            ),
            anchor_key=anchor_key,
            source=source or "protected_hedge",
            admission_score=0.0,
            suggested_probe_reason="post_final_shared_retained_anchor",
            click_budget=1 if family == "click" else 0,
            move_probe_budget=1 if family != "click" else 0,
            rotate_cost=0.0,
            confidence="low",
            runtime_probe_ok=True,
            component_id=component_id,
            transition_model_candidate_family=family,
        )

    def _try_consume_post_final_shared_retained_route_reseed(
        self,
        *,
        state: ECAState,
        pending_stats: dict[str, Any],
        no_target_disposition: str,
    ) -> SelectedTargetSummary | None:
        if not self._post_final_shared_retained_route_anchor_active(step_index=int(state.step_index)):
            return None
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor or bool(anchor.get("reseed_used", False)):
            return None
        same_route_hold_active = self._post_final_shared_retained_route_same_route_hold_active(
            step_index=int(state.step_index),
        )
        if (
            int(pending_stats.get("live_escape_candidate_count", 0) or 0) > 0
            and not same_route_hold_active
        ):
            return None
        if not (
            bool(pending_stats.get("selected_target_empty_with_candidate_pool", False))
            or not str(no_target_disposition or "").strip()
            or str(no_target_disposition or "") in {"preterminal_dead_revisit", "hard_terminal"}
        ):
            return None
        retained_summary = self._selected_target_summary_from_retained_route_anchor()
        if retained_summary is None or self._selected_target_summary_effectively_empty(
            selected_target_summary=retained_summary
        ):
            return None
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target={},
                selected_target_summary=retained_summary,
                target_viability_reason=str(anchor.get("last_viability_reason", "") or ""),
                target_viability_drop_reason=str(anchor.get("last_viability_drop_reason", "") or ""),
            )
        )
        if late_exit_class not in {"recoverable_exhaustion", "collapse_without_anchor"}:
            return None
        if late_exit_class == "recoverable_exhaustion" and not same_route:
            return None
        effective_step_index = int(state.step_index)
        anchor["reseed_used"] = True
        anchor["last_reseed_step_idx"] = effective_step_index
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        self._arm_post_final_shared_retained_route_same_route_hold(
            step_index=effective_step_index,
        )
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(late_exit_class or "")
        self.last_post_final_shared_after_exit_same_route_anchor = bool(same_route)
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            float(continuity_score or 0.0),
            3,
        )
        if same_route:
            self._record_post_final_shared_after_exit_same_route_anchor_event(
                step_index=effective_step_index,
            )
        self.last_post_final_shared_retained_route_reseed_issued = True
        self.last_post_final_shared_retained_route_reseed_consumed = True
        self.last_post_final_shared_retained_route_reseed_success = True
        self.last_post_final_shared_retained_route_reseed_reason = (
            str(late_exit_class or "") or "retained_route_anchor"
        )
        self.post_final_shared_retained_route_reseed_issue_count += 1
        self.post_final_shared_retained_route_reseed_consume_count += 1
        self.post_final_shared_retained_route_reseed_success_count += 1
        summary_payload = retained_summary.to_dict()
        self.last_selected_target_summary = summary_payload
        candidate_snapshot = {
            "candidate_id": str(retained_summary.candidate_id or ""),
            "level_idx": int(state.level_number),
            "component_id": str(retained_summary.component_id or ""),
            "anchor_key": str(retained_summary.anchor_key or ""),
            "source": str(retained_summary.source or ""),
            "family": str(retained_summary.transition_model_candidate_family or "move"),
            "admission_score": 0.0,
            "suggested_probe_reason": "post_final_shared_retained_route_reseed",
        }
        reseed_ticket = {
            "component_id": str(retained_summary.component_id or ""),
            "anchor_key": str(retained_summary.anchor_key or ""),
            "candidate_id": str(retained_summary.candidate_id or ""),
            "source": str(retained_summary.source or ""),
            "suggested_probe_reason": "post_final_shared_retained_route_reseed",
            "confidence": str(retained_summary.confidence or "low"),
            "seed_kind": "retained_route_anchor",
            "candidate_snapshot": candidate_snapshot,
            "open_reason": "post_final_shared_retained_route_reseed",
            "level_idx": int(state.level_number),
            "attach_count": 1,
        }
        self._issue_post_final_shared_continuation_lock(
            ticket=reseed_ticket,
            step_index=effective_step_index,
            selected_target_summary=summary_payload,
            candidate_snapshot=candidate_snapshot,
        )
        self._issue_post_final_shared_continuation_target_psa_credit(
            ticket=reseed_ticket,
            step_index=effective_step_index,
            source_override="retained_route_reseed",
        )
        self._apply_post_final_shared_continuation_probe_refresh(
            step_index=effective_step_index,
            selected_target_summary=summary_payload,
            reason="post_final_shared_retained_route_reseed",
        )
        self.note_queue_exhaustion_recovery_source("post_final_shared_retained_route_reseed")
        return retained_summary

    def _try_consume_post_final_shared_retained_route_identity_carry(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        previous_selected_target_summary: SelectedTargetSummary | None,
        target_rotation_event: dict[str, Any] | None,
        target_viability_reason: str,
        target_viability_drop_reason: str,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
    ) -> SelectedTargetSummary | None:
        if self._post_final_shared_active():
            return None
        if not self._post_final_shared_retained_route_anchor_active(step_index=int(state.step_index)):
            return None
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor or bool(anchor.get("identity_carry_used", False)):
            return None
        if (
            selected_target_summary is None
            or self._selected_target_summary_effectively_empty(
                selected_target_summary=selected_target_summary
            )
        ):
            return None
        anchor_matches_summary, _ = self._post_final_shared_retained_route_anchor_matches_selected_target_summary(
            selected_target_summary=selected_target_summary,
        )
        if anchor_matches_summary:
            return None
        same_route_previous_summary, previous_summary_score = (
            self._post_final_shared_retained_route_anchor_matches_selected_target_summary(
                selected_target_summary=previous_selected_target_summary,
            )
        )
        retained_summary = self._selected_target_summary_from_retained_route_anchor()
        if retained_summary is None or self._selected_target_summary_effectively_empty(
            selected_target_summary=retained_summary
        ):
            return None
        rotation_reason = str((target_rotation_event or {}).get("reason", "") or "")
        selected_reason = str(selected_target_summary.suggested_probe_reason or "")
        drift_reason = (
            rotation_reason
            or selected_reason
            or str(target_viability_drop_reason or "")
            or str(target_viability_reason or "")
        )
        if not (
            drift_reason.startswith("fresh_target_after_rotation")
            or selected_reason in {
                "ir_low_gain_div",
                "ir_retention",
                "current_target_click_family_exhausted",
            }
            or str(target_viability_drop_reason or "")
            in {
                "target_move_probe_exhausted",
                "target_family_probe_exhausted",
                "fresh_target_minimal_probe_exhausted",
            }
        ):
            return None
        same_route_effective_contract, effective_contract_score = (
            self._post_final_shared_retained_route_anchor_matches_effective_local_contract(
                effective_source=effective_local_contract_source,
                contract_component_id=effective_local_contract_component_id,
                contract_anchor_key=effective_local_contract_anchor,
            )
        )
        same_route_continuation_identity, continuation_identity_score = (
            self._post_final_shared_retained_route_anchor_matches_active_continuation_identity(
                step_index=int(state.step_index),
            )
        )
        same_route_current_contract, current_contract_score = (
            self._post_final_shared_retained_route_anchor_matches_current_contract()
        )
        continuity_score = max(
            float(previous_summary_score or 0.0),
            float(effective_contract_score or 0.0),
            float(continuation_identity_score or 0.0),
            float(current_contract_score or 0.0),
        )
        continuity_refresh_hold_active = bool(
            bool(anchor.get("refresh_used", False))
            and self._post_final_shared_retained_route_same_route_hold_active(
                step_index=int(state.step_index),
            )
        )
        effective_step_index = int(state.step_index)
        recent_same_route_event_active = bool(
            int(anchor.get("last_same_route_event_step_idx", -10_000) or -10_000)
            >= max(0, effective_step_index - 2)
        )
        if not (
            same_route_previous_summary
            or same_route_effective_contract
            or same_route_continuation_identity
            or same_route_current_contract
            or continuity_refresh_hold_active
            or recent_same_route_event_active
        ):
            return None
        if continuity_refresh_hold_active:
            continuity_score = max(float(continuity_score or 0.0), 0.5)
        if recent_same_route_event_active:
            continuity_score = max(float(continuity_score or 0.0), 0.6)
        anchor["identity_carry_used"] = True
        anchor["last_identity_carry_step_idx"] = effective_step_index
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        self._arm_post_final_shared_retained_route_same_route_hold(
            step_index=effective_step_index,
        )
        self.last_post_final_shared_after_exit_psa_late_exit_class = "recoverable_exhaustion"
        self.last_post_final_shared_after_exit_same_route_anchor = True
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            float(continuity_score or 0.0),
            3,
        )
        self._record_post_final_shared_after_exit_same_route_anchor_event(
            step_index=effective_step_index,
        )
        self.last_post_final_shared_retained_route_identity_carry_issued = True
        self.last_post_final_shared_retained_route_identity_carry_consumed = True
        self.last_post_final_shared_retained_route_identity_carry_success = True
        self.last_post_final_shared_retained_route_identity_carry_reason = (
            str(drift_reason or "") or "post_final_shared_retained_route_identity_carry"
        )
        self.post_final_shared_retained_route_identity_carry_issue_count += 1
        self.post_final_shared_retained_route_identity_carry_consume_count += 1
        self.post_final_shared_retained_route_identity_carry_success_count += 1
        summary_payload = retained_summary.to_dict()
        self.last_selected_target_summary = summary_payload
        candidate_snapshot = {
            "candidate_id": str(retained_summary.candidate_id or ""),
            "level_idx": int(state.level_number),
            "component_id": str(retained_summary.component_id or ""),
            "anchor_key": str(retained_summary.anchor_key or ""),
            "source": str(retained_summary.source or ""),
            "family": str(retained_summary.transition_model_candidate_family or "move"),
            "admission_score": float(retained_summary.admission_score or 0.0),
            "suggested_probe_reason": "post_final_shared_retained_route_identity_carry",
        }
        carry_ticket = {
            "component_id": str(retained_summary.component_id or ""),
            "anchor_key": str(retained_summary.anchor_key or ""),
            "candidate_id": str(retained_summary.candidate_id or ""),
            "source": str(retained_summary.source or ""),
            "suggested_probe_reason": "post_final_shared_retained_route_identity_carry",
            "confidence": str(retained_summary.confidence or "low"),
            "seed_kind": "retained_route_anchor",
            "candidate_snapshot": candidate_snapshot,
            "open_reason": "post_final_shared_retained_route_identity_carry",
            "level_idx": int(state.level_number),
            "attach_count": 1,
        }
        self._issue_post_final_shared_continuation_lock(
            ticket=carry_ticket,
            step_index=effective_step_index,
            selected_target_summary=summary_payload,
            candidate_snapshot=candidate_snapshot,
        )
        self._issue_post_final_shared_continuation_target_psa_credit(
            ticket=carry_ticket,
            step_index=effective_step_index,
            source_override="retained_route_identity_carry",
        )
        self._apply_post_final_shared_continuation_probe_refresh(
            step_index=effective_step_index,
            selected_target_summary=summary_payload,
            reason="post_final_shared_retained_route_identity_carry",
        )
        self.note_queue_exhaustion_recovery_source("post_final_shared_retained_route_identity_carry")
        return retained_summary

    def _issue_or_refresh_post_final_shared_retained_route_anchor(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        current_target_viability_reason: str = "",
        current_target_viability_drop_reason: str = "",
    ) -> None:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        effective_summary = self._post_final_shared_effective_route_summary(
            contract=item,
            selected_target_summary=selected_target_summary,
            step_index=int(state.step_index),
        )
        if effective_summary is None:
            return
        component_id = str(effective_summary.component_id or "")
        anchor_key = str(effective_summary.anchor_key or "")
        candidate_id = str(effective_summary.candidate_id or "")
        if not component_id and not anchor_key and not candidate_id:
            return
        existing = dict(self.last_post_final_shared_retained_route_anchor or {})
        same_identity = bool(
            existing
            and (
                (component_id and str(existing.get("component_id", "") or "") == component_id)
                or (anchor_key and str(existing.get("anchor_key", "") or "") == anchor_key)
                or (candidate_id and str(existing.get("candidate_id", "") or "") == candidate_id)
            )
        )
        anchor = dict(existing if same_identity else {})
        anchor.update(
            {
                "component_id": component_id,
                "anchor_key": anchor_key,
                "candidate_id": candidate_id,
                "level_idx": int(state.level_number),
                "source": str(effective_summary.source or ""),
                "source_family": str(
                    effective_summary.transition_model_candidate_family
                    or item.get("action_family", "")
                    or item.get("family", "")
                    or ""
                ),
                "effective_local_contract_source": str(
                    self.last_effective_local_contract_source
                    or self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_NONE
                ),
                "promotion_turn": int(state.step_index),
                "last_progress_signal": str(self.last_post_final_shared_contract_progress_signal or ""),
                "last_viability_reason": str(current_target_viability_reason or ""),
                "last_viability_drop_reason": str(current_target_viability_drop_reason or ""),
                "probe_budget_class": self._post_final_shared_probe_budget_class(
                    viability_drop_reason=current_target_viability_drop_reason,
                ),
                "ttl": int(self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_DURABILITY_STEPS),
                "after_exit_expires_turn": int(
                    anchor.get("after_exit_expires_turn", -1) or -1
                ),
                "same_route_hold_expires_turn": int(
                    anchor.get("same_route_hold_expires_turn", -1) or -1
                ),
                "refresh_used": False,
                "durability_refresh_used": False,
                "family_probe_carry_used": False,
                "move_probe_carry_used": False,
                "last_same_route_event_step_idx": int(
                    anchor.get("last_same_route_event_step_idx", -1) or -1
                ),
                "same_route_event_count": int(anchor.get("same_route_event_count", 0) or 0),
            }
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        if same_identity:
            self.post_final_shared_retained_route_anchor_refresh_count += 1
        else:
            self.post_final_shared_retained_route_anchor_issue_count += 1

    def _arm_post_final_shared_retained_route_anchor_after_exit(
        self,
        *,
        step_index: int,
    ) -> None:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return
        anchor["after_exit_expires_turn"] = int(step_index) + int(
            self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_DURABILITY_STEPS
        )
        anchor["refresh_used"] = False
        anchor["after_exit_step_idx"] = int(step_index)
        self.last_post_final_shared_retained_route_anchor = anchor

    def _arm_post_final_shared_retained_route_same_route_hold(
        self,
        *,
        step_index: int,
    ) -> None:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return
        anchor["same_route_hold_expires_turn"] = max(
            int(anchor.get("same_route_hold_expires_turn", -1) or -1),
            int(step_index) + int(self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_DURABILITY_STEPS),
        )
        self.last_post_final_shared_retained_route_anchor = anchor

    def _post_final_shared_retained_route_same_route_hold_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        expires_turn = int(anchor.get("same_route_hold_expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _maybe_refresh_post_final_shared_retained_route_persistence_after_exit(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
    ) -> None:
        if self._post_final_shared_active():
            return
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return
        if not bool(anchor.get("refresh_used", False)):
            return
        effective_step_index = int(state.step_index)
        if not self._post_final_shared_retained_route_anchor_active(step_index=effective_step_index):
            return
        if int(anchor.get("after_exit_persistence_refresh_count", 0) or 0) >= 2:
            return
        same_route_summary, summary_score = (
            self._post_final_shared_retained_route_anchor_matches_selected_target_summary(
                selected_target_summary=selected_target_summary,
            )
        )
        same_route_state_selected, state_selected_score = (
            self._post_final_shared_retained_route_anchor_matches_state_selected_target(
                state=state,
            )
        )
        same_route_effective_contract, effective_contract_score = (
            self._post_final_shared_retained_route_anchor_matches_effective_local_contract(
                effective_source=effective_local_contract_source,
                contract_component_id=effective_local_contract_component_id,
                contract_anchor_key=effective_local_contract_anchor,
            )
        )
        if not (
            same_route_summary
            or same_route_state_selected
            or same_route_effective_contract
        ):
            return
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        anchor["same_route_hold_expires_turn"] = max(
            int(anchor.get("same_route_hold_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        anchor["after_exit_persistence_refresh_count"] = int(
            anchor.get("after_exit_persistence_refresh_count", 0) or 0
        ) + 1
        self.last_post_final_shared_retained_route_anchor = anchor
        self.post_final_shared_retained_route_persistence_refresh_count += 1
        self.last_post_final_shared_retained_route_persistence_refreshed = True
        self.last_post_final_shared_after_exit_same_route_anchor = True
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            max(
                float(summary_score or 0.0),
                float(state_selected_score or 0.0),
                float(effective_contract_score or 0.0),
                0.5,
            ),
            3,
        )
        self._record_post_final_shared_after_exit_same_route_anchor_event(
            step_index=effective_step_index,
        )

    def _maybe_apply_post_final_shared_same_route_durability_refresh_after_exit(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any] | None = None,
        selected_target_summary: SelectedTargetSummary | None = None,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
        target_viability_reason: str = "",
        target_viability_drop_reason: str = "",
    ) -> None:
        if self._post_final_shared_active():
            return
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return
        if not bool(anchor.get("refresh_used", False)):
            return
        if bool(anchor.get("durability_refresh_used", False)):
            return
        if int(anchor.get("after_exit_persistence_refresh_count", 0) or 0) <= 0:
            return
        effective_step_index = int(state.step_index)
        if not self._post_final_shared_retained_route_anchor_active(step_index=effective_step_index):
            return
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target=dict(local_target or {}),
                selected_target_summary=selected_target_summary,
                target_viability_reason=str(
                    target_viability_reason
                    or getattr(state, "current_target_viability_reason", "")
                    or ""
                ),
                target_viability_drop_reason=str(
                    target_viability_drop_reason
                    or getattr(state, "current_target_viability_drop_reason", "")
                    or ""
                ),
                effective_local_contract_source=effective_local_contract_source,
                effective_local_contract_component_id=effective_local_contract_component_id,
                effective_local_contract_anchor=effective_local_contract_anchor,
            )
        )
        if late_exit_class != "recoverable_exhaustion" or not same_route:
            return
        anchor["durability_refresh_used"] = True
        anchor["last_durability_refresh_step_idx"] = effective_step_index
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        anchor["same_route_hold_expires_turn"] = max(
            int(anchor.get("same_route_hold_expires_turn", -1) or -1),
            effective_step_index + 1,
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        self.post_final_shared_same_route_durability_refresh_count += 1
        self.last_post_final_shared_same_route_durability_refreshed = True
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(late_exit_class or "")
        self.last_post_final_shared_after_exit_same_route_anchor = True
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            max(
                float(self.last_post_final_shared_after_exit_anchor_continuity_score or 0.0),
                float(continuity_score or 0.0),
                0.5,
            ),
            3,
        )
        self._record_post_final_shared_after_exit_same_route_anchor_event(
            step_index=effective_step_index,
        )
        refresh_summary = (
            self._selected_target_summary_from_retained_route_anchor()
            or selected_target_summary
        )
        self._apply_post_final_shared_continuation_probe_refresh(
            step_index=effective_step_index,
            selected_target_summary=refresh_summary,
            reason="post_final_shared_same_route_durability_refresh",
        )

    def _maybe_apply_post_final_shared_same_route_family_probe_carry_after_exit(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any] | None = None,
        selected_target_summary: SelectedTargetSummary | None = None,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
        target_viability_reason: str = "",
        target_viability_drop_reason: str = "",
        current_target_verify_budget: int = 0,
    ) -> bool:
        if self._post_final_shared_active():
            return False
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False
        if not bool(anchor.get("refresh_used", False)):
            return False
        if not bool(anchor.get("durability_refresh_used", False)):
            return False
        if bool(anchor.get("family_probe_carry_used", False)):
            return False
        effective_step_index = int(state.step_index)
        if not self._post_final_shared_retained_route_anchor_active(step_index=effective_step_index):
            return False
        viability_reason = str(target_viability_reason or "")
        viability_drop_reason = str(target_viability_drop_reason or "")
        if viability_drop_reason != "target_family_probe_exhausted" and viability_reason != "psa_sweep_dead":
            return False
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target=dict(local_target or {}),
                selected_target_summary=selected_target_summary,
                target_viability_reason=viability_reason,
                target_viability_drop_reason=viability_drop_reason,
                effective_local_contract_source=effective_local_contract_source,
                effective_local_contract_component_id=effective_local_contract_component_id,
                effective_local_contract_anchor=effective_local_contract_anchor,
            )
        )
        if late_exit_class != "recoverable_exhaustion" or not same_route:
            return False
        anchor["family_probe_carry_used"] = True
        anchor["last_family_probe_carry_step_idx"] = effective_step_index
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 2,
        )
        anchor["same_route_hold_expires_turn"] = max(
            int(anchor.get("same_route_hold_expires_turn", -1) or -1),
            effective_step_index + 2,
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        self.post_final_shared_same_route_family_probe_carry_count += 1
        self.last_post_final_shared_same_route_family_probe_carried = True
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(late_exit_class or "")
        self.last_post_final_shared_after_exit_same_route_anchor = True
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            max(
                float(self.last_post_final_shared_after_exit_anchor_continuity_score or 0.0),
                float(continuity_score or 0.0),
                0.5,
            ),
            3,
        )
        self._record_post_final_shared_after_exit_same_route_anchor_event(
            step_index=effective_step_index,
        )
        target_component_id = str(
            (dict(local_target or {})).get("component_id", "")
            or (selected_target_summary.component_id if selected_target_summary is not None else "")
            or anchor.get("component_id", "")
            or ""
        )
        target_anchor_key = str(
            (
                self._anchor_key(level_number=state.level_number, component=dict(local_target or {}))
                if local_target
                else ""
            )
            or (selected_target_summary.anchor_key if selected_target_summary is not None else "")
            or anchor.get("anchor_key", "")
            or ""
        )
        if target_component_id:
            self.target_blacklist.pop(target_component_id, None)
        if target_anchor_key:
            self.target_anchor_blacklist.pop(target_anchor_key, None)
        if target_component_id:
            self._set_target_psa_state(
                target_component_id,
                state_name=self.TARGET_PSA_STATE_VERIFY_ONCE,
                verify_budget=max(int(current_target_verify_budget or 0), 2),
                psa_reason="post_final_shared_same_route_family_probe_carry",
                viability_score=0.0,
                click_banned=False,
                step_idx=effective_step_index,
                expires_at=effective_step_index + 2,
            )
        return True

    def _maybe_apply_post_final_shared_same_route_move_probe_carry_after_exit(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any] | None = None,
        selected_target_summary: SelectedTargetSummary | None = None,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
        target_viability_reason: str = "",
        target_viability_drop_reason: str = "",
        current_target_verify_budget: int = 0,
    ) -> bool:
        if self._post_final_shared_active():
            return False
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False
        if not bool(anchor.get("refresh_used", False)):
            return False
        if int(anchor.get("after_exit_persistence_refresh_count", 0) or 0) <= 0:
            return False
        if bool(anchor.get("move_probe_carry_used", False)):
            return False
        effective_step_index = int(state.step_index)
        if not self._post_final_shared_retained_route_anchor_active(step_index=effective_step_index):
            return False
        viability_reason = str(target_viability_reason or "")
        viability_drop_reason = str(target_viability_drop_reason or "")
        if viability_drop_reason not in {
            "target_move_probe_exhausted",
            "fresh_target_minimal_probe_exhausted",
        }:
            return False
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target=dict(local_target or {}),
                selected_target_summary=selected_target_summary,
                target_viability_reason=viability_reason,
                target_viability_drop_reason=viability_drop_reason,
                effective_local_contract_source=effective_local_contract_source,
                effective_local_contract_component_id=effective_local_contract_component_id,
                effective_local_contract_anchor=effective_local_contract_anchor,
            )
        )
        if late_exit_class != "recoverable_exhaustion" or not same_route:
            return False
        anchor["move_probe_carry_used"] = True
        anchor["last_move_probe_carry_step_idx"] = effective_step_index
        anchor["after_exit_expires_turn"] = max(
            int(anchor.get("after_exit_expires_turn", -1) or -1),
            effective_step_index + 2,
        )
        anchor["same_route_hold_expires_turn"] = max(
            int(anchor.get("same_route_hold_expires_turn", -1) or -1),
            effective_step_index + 2,
        )
        self.last_post_final_shared_retained_route_anchor = anchor
        self.post_final_shared_same_route_move_probe_carry_count += 1
        self.last_post_final_shared_same_route_move_probe_carried = True
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(late_exit_class or "")
        self.last_post_final_shared_after_exit_same_route_anchor = True
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            max(
                float(self.last_post_final_shared_after_exit_anchor_continuity_score or 0.0),
                float(continuity_score or 0.0),
                0.5,
            ),
            3,
        )
        self._record_post_final_shared_after_exit_same_route_anchor_event(
            step_index=effective_step_index,
        )
        target_component_id = str(
            (dict(local_target or {})).get("component_id", "")
            or (selected_target_summary.component_id if selected_target_summary is not None else "")
            or anchor.get("component_id", "")
            or ""
        )
        target_anchor_key = str(
            (
                self._anchor_key(level_number=state.level_number, component=dict(local_target or {}))
                if local_target
                else ""
            )
            or (selected_target_summary.anchor_key if selected_target_summary is not None else "")
            or anchor.get("anchor_key", "")
            or ""
        )
        if target_component_id:
            self.target_blacklist.pop(target_component_id, None)
        if target_anchor_key:
            self.target_anchor_blacklist.pop(target_anchor_key, None)
        if target_component_id:
            self._set_target_psa_state(
                target_component_id,
                state_name=self.TARGET_PSA_STATE_VERIFY_ONCE,
                verify_budget=max(int(current_target_verify_budget or 0), 2),
                psa_reason="post_final_shared_same_route_move_probe_carry",
                viability_score=0.0,
                click_banned=False,
                step_idx=effective_step_index,
                expires_at=effective_step_index + 2,
            )
        return True

    def _post_final_shared_retained_route_anchor_active(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False
        if bool((self.last_protected_hedge_contract or {}).get("post_final_shared_active", False)):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        level_idx = int(anchor.get("level_idx", -1) or -1)
        if self.last_state is not None and level_idx >= 0 and int(self.last_state.level_number) != level_idx:
            return False
        expires_turn = int(anchor.get("after_exit_expires_turn", -1) or -1)
        return expires_turn >= 0 and effective_step_index <= expires_turn

    def _post_final_shared_retained_route_anchor_matches_local_target(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor or not local_target:
            return False, 0.0
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        component_id = str(local_target.get("component_id", "") or "")
        target_anchor_key = self._anchor_key(level_number=state.level_number, component=local_target)
        component_match = bool(anchor_component_id and component_id and anchor_component_id == component_id)
        anchor_match = bool(anchor_anchor_key and target_anchor_key and anchor_anchor_key == target_anchor_key)
        if component_match and anchor_match:
            return True, 1.0
        if component_match or anchor_match:
            return True, 0.75
        return False, 0.0

    def _post_final_shared_retained_route_anchor_matches_selected_target_summary(
        self,
        *,
        selected_target_summary: SelectedTargetSummary | None,
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor or selected_target_summary is None:
            return False, 0.0
        if self._selected_target_summary_effectively_empty(
            selected_target_summary=selected_target_summary
        ):
            return False, 0.0
        component_match = bool(
            str(anchor.get("component_id", "") or "")
            and str(selected_target_summary.component_id or "")
            and str(anchor.get("component_id", "") or "") == str(selected_target_summary.component_id or "")
        )
        anchor_match = bool(
            str(anchor.get("anchor_key", "") or "")
            and str(selected_target_summary.anchor_key or "")
            and str(anchor.get("anchor_key", "") or "") == str(selected_target_summary.anchor_key or "")
        )
        candidate_match = bool(
            str(anchor.get("candidate_id", "") or "")
            and str(selected_target_summary.candidate_id or "")
            and str(anchor.get("candidate_id", "") or "") == str(selected_target_summary.candidate_id or "")
        )
        if (component_match and anchor_match) or candidate_match:
            return True, 1.0
        if component_match or anchor_match:
            return True, 0.75
        return False, 0.0

    def _post_final_shared_retained_route_anchor_matches_state_selected_target(
        self,
        *,
        state: ECAState,
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False, 0.0
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        state_component_id = str(getattr(state, "selected_target_id", "") or "")
        state_anchor_key = str(getattr(state, "selected_target_anchor", "") or "")
        component_match = bool(
            anchor_component_id
            and state_component_id
            and anchor_component_id == state_component_id
        )
        anchor_match = bool(
            anchor_anchor_key
            and state_anchor_key
            and anchor_anchor_key == state_anchor_key
        )
        if component_match and anchor_match:
            return True, 1.0
        if component_match or anchor_match:
            return True, 0.75
        return False, 0.0

    def _post_final_shared_retained_route_anchor_matches_current_contract(
        self,
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        item = dict(self.last_protected_hedge_contract or {})
        if not anchor or not item:
            return False, 0.0
        contract_component_id = str(
            item.get("promoted_selected_target_component_id", "")
            or item.get("component_id", "")
            or ""
        )
        contract_anchor_key = str(
            item.get("promoted_selected_target_anchor", "")
            or item.get("anchor_key", "")
            or self._protected_hedge_contract_key(item)
            or ""
        )
        contract_candidate_id = str(
            item.get("promoted_selected_target_candidate_id", "") or ""
        )
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        anchor_candidate_id = str(anchor.get("candidate_id", "") or "")
        component_match = bool(
            anchor_component_id
            and contract_component_id
            and anchor_component_id == contract_component_id
        )
        anchor_match = bool(
            anchor_anchor_key
            and contract_anchor_key
            and anchor_anchor_key == contract_anchor_key
        )
        candidate_match = bool(
            anchor_candidate_id
            and contract_candidate_id
            and anchor_candidate_id == contract_candidate_id
        )
        if (component_match and anchor_match) or candidate_match:
            return True, 1.0
        if component_match or anchor_match:
            return True, 0.75
        return False, 0.0

    def _post_final_shared_retained_route_anchor_matches_effective_local_contract(
        self,
        *,
        effective_source: str | None = None,
        contract_component_id: str | None = None,
        contract_anchor_key: str | None = None,
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False, 0.0
        effective_source = str(
            effective_source
            if effective_source is not None
            else (self.last_effective_local_contract_source or "")
        )
        if effective_source in {
            "",
            self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_NONE,
            self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_NO_TARGET,
        }:
            return False, 0.0
        contract_component_id = str(
            contract_component_id
            if contract_component_id is not None
            else (self.last_effective_local_contract_component_id or "")
        )
        contract_anchor_key = str(
            contract_anchor_key
            if contract_anchor_key is not None
            else (self.last_effective_local_contract_anchor or "")
        )
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        component_match = bool(
            anchor_component_id
            and contract_component_id
            and anchor_component_id == contract_component_id
        )
        anchor_match = bool(
            anchor_anchor_key
            and contract_anchor_key
            and anchor_anchor_key == contract_anchor_key
        )
        if component_match and anchor_match:
            return True, 1.0
        if component_match or anchor_match:
            return True, 0.75
        return False, 0.0

    def _post_final_shared_retained_route_anchor_matches_active_continuation_identity(
        self,
        *,
        step_index: int,
    ) -> tuple[bool, float]:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor:
            return False, 0.0
        items: list[dict[str, Any]] = []
        if self._post_final_shared_continuation_lock_active(step_index=step_index):
            items.append(dict(self.last_post_final_shared_continuation_lock or {}))
        if self._post_final_shared_continuation_ticket_active(step_index=step_index):
            items.append(dict(self.last_post_final_shared_continuation_ticket or {}))
        if not items:
            return False, 0.0
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        anchor_candidate_id = str(anchor.get("candidate_id", "") or "")
        best_score = 0.0
        for item in items:
            component_match = bool(
                anchor_component_id
                and str(item.get("component_id", "") or "")
                and anchor_component_id == str(item.get("component_id", "") or "")
            )
            anchor_match = bool(
                anchor_anchor_key
                and str(item.get("anchor_key", "") or "")
                and anchor_anchor_key == str(item.get("anchor_key", "") or "")
            )
            candidate_match = bool(
                anchor_candidate_id
                and str(item.get("candidate_id", "") or "")
                and anchor_candidate_id == str(item.get("candidate_id", "") or "")
            )
            if (component_match and anchor_match) or candidate_match:
                return True, 1.0
            if component_match or anchor_match:
                best_score = max(best_score, 0.75)
        return (best_score > 0.0), best_score

    def _classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
        selected_target_summary: SelectedTargetSummary | None,
        target_viability_reason: str,
        target_viability_drop_reason: str,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
    ) -> tuple[str, bool, float]:
        last_exit_step_idx = int(self.last_post_final_shared_exit_step_idx or -1)
        if last_exit_step_idx < 0:
            return "", False, 0.0
        if bool((self.last_protected_hedge_contract or {}).get("post_final_shared_active", False)):
            return "", False, 0.0
        if int(state.step_index) > (
            last_exit_step_idx + self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_DURABILITY_STEPS
        ):
            return "", False, 0.0
        if not self._post_final_shared_retained_route_anchor_active(step_index=int(state.step_index)):
            if local_target or (
                selected_target_summary is not None
                and not self._selected_target_summary_effectively_empty(
                    selected_target_summary=selected_target_summary
                )
            ):
                if str(target_viability_reason or "") or str(target_viability_drop_reason or ""):
                    return "hard_dead", False, 0.0
            return "collapse_without_anchor", False, 0.0
        same_route_local, local_score = self._post_final_shared_retained_route_anchor_matches_local_target(
            state=state,
            local_target=local_target,
        )
        same_route_summary, summary_score = (
            self._post_final_shared_retained_route_anchor_matches_selected_target_summary(
                selected_target_summary=selected_target_summary,
            )
        )
        same_route_state_selected, state_selected_score = (
            self._post_final_shared_retained_route_anchor_matches_state_selected_target(
                state=state,
            )
        )
        same_route_effective_contract, effective_contract_score = (
            self._post_final_shared_retained_route_anchor_matches_effective_local_contract(
                effective_source=effective_local_contract_source,
                contract_component_id=effective_local_contract_component_id,
                contract_anchor_key=effective_local_contract_anchor,
            )
        )
        same_route_continuation_identity, continuation_identity_score = (
            self._post_final_shared_retained_route_anchor_matches_active_continuation_identity(
                step_index=int(state.step_index),
            )
        )
        same_route_contract, contract_score = (
            self._post_final_shared_retained_route_anchor_matches_current_contract()
        )
        same_route = bool(
            same_route_local
            or same_route_summary
            or same_route_state_selected
            or same_route_effective_contract
            or same_route_continuation_identity
            or same_route_contract
        )
        continuity_score = max(
            float(local_score),
            float(summary_score),
            float(state_selected_score),
            float(effective_contract_score),
            float(continuation_identity_score),
            float(contract_score),
        )
        if (
            not same_route
            and self._post_final_shared_retained_route_same_route_hold_active(
                step_index=int(state.step_index),
            )
        ):
            same_route = True
            continuity_score = max(float(continuity_score or 0.0), 0.5)
        viability_reason = str(target_viability_reason or "")
        viability_drop_reason = str(target_viability_drop_reason or "")
        if same_route and viability_drop_reason in {
            "target_move_probe_exhausted",
            "target_family_probe_exhausted",
            "fresh_target_minimal_probe_exhausted",
        }:
            return "recoverable_exhaustion", True, continuity_score
        if not same_route:
            anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
            grace_stage = int(anchor.get("pre_anchor_grace_stage", 0) or 0)
            within_grace_window = bool(
                anchor
                and int(state.step_index) <= int(anchor.get("after_exit_step_idx", -1) or -1)
                    + self.TARGET_POST_FINAL_SHARED_AFTER_EXIT_PRE_ANCHOR_GRACE_STEPS
            )
            anchor_contract_source = str(anchor.get("effective_local_contract_source", "") or "")
            # Stage 1: initial grace (first call, current-info only)
            if grace_stage == 0 and within_grace_window and anchor:
                # psa_anchor_locked_dead suppresses initial grace (hard death)
                locked_dead_block = viability_reason == "psa_anchor_locked_dead"
                has_death_signal = bool(
                    viability_drop_reason in {
                        "target_move_probe_exhausted",
                        "target_family_probe_exhausted",
                        "fresh_target_minimal_probe_exhausted",
                    }
                    or viability_reason in {
                        "psa_dead_end",
                        "psa_sweep_dead",
                    }
                )
                if has_death_signal:
                    self.post_final_shared_after_exit_pre_anchor_grace_eligible_count += 1
                if locked_dead_block and has_death_signal:
                    self.post_final_shared_after_exit_pre_anchor_grace_suppressed_locked_dead_count += 1
                if has_death_signal and not locked_dead_block:
                    # Source-aware continuity score
                    if anchor_contract_source == "selected_target":
                        grace_score = 0.55
                    elif anchor_contract_source == "protected_hedge":
                        grace_score = 0.35
                    else:
                        grace_score = 0.4
                    anchor["pre_anchor_grace_stage"] = 1
                    anchor["pre_anchor_grace_used"] = True
                    self.last_post_final_shared_retained_route_anchor = anchor
                    self.post_final_shared_after_exit_pre_anchor_grace_count += 1
                    self.last_post_final_shared_after_exit_pre_anchor_grace_applied = True
                    return "recoverable_exhaustion", True, max(continuity_score, grace_score)
            # Stage 2: extension (1 step after stage 1 fired)
            elif grace_stage == 1 and anchor:
                target_health_now = str(
                    getattr(
                        getattr(self, "_last_target_health_result", None),
                        "health", "",
                    ) or ""
                )
                anchor_still_active = self._post_final_shared_retained_route_anchor_active(
                    step_index=int(state.step_index)
                )
                if (
                    target_health_now == "live"
                    and anchor_still_active
                    and viability_reason != "psa_anchor_locked_dead"
                ):
                    # Extend: grant one more step
                    anchor["pre_anchor_grace_stage"] = 2
                    anchor["after_exit_expires_turn"] = max(
                        int(anchor.get("after_exit_expires_turn", -1) or -1),
                        int(state.step_index) + 1,
                    )
                    self.last_post_final_shared_retained_route_anchor = anchor
                    self.post_final_shared_after_exit_pre_anchor_grace_count += 1
                    self.post_final_shared_after_exit_pre_anchor_grace_stage2_extend_count += 1
                    self.last_post_final_shared_after_exit_pre_anchor_grace_applied = True
                    return "recoverable_exhaustion", True, max(continuity_score, 0.5)
                else:
                    # Cut: locked_dead or health not live → no extension
                    anchor["pre_anchor_grace_stage"] = 2
                    self.post_final_shared_after_exit_pre_anchor_grace_stage2_cut_count += 1
                    self.last_post_final_shared_retained_route_anchor = anchor
        has_route_signal = bool(
            local_target
            or (
                selected_target_summary is not None
                and not self._selected_target_summary_effectively_empty(
                    selected_target_summary=selected_target_summary
                )
            )
        )
        if has_route_signal and not same_route:
            return "identity_drift", False, continuity_score
        if not has_route_signal:
            return "collapse_without_anchor", False, continuity_score
        if viability_reason or viability_drop_reason:
            return "hard_dead", same_route, continuity_score
        return "", same_route, continuity_score

    def _apply_post_final_shared_probe_continuity_from_retained_anchor(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any],
        selected_target_summary: SelectedTargetSummary | None,
    ) -> bool:
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if not anchor or bool(anchor.get("refresh_used", False)):
            return False
        anchor["refresh_used"] = True
        anchor["last_refresh_step_idx"] = int(state.step_index)
        self.last_post_final_shared_retained_route_anchor = anchor
        self._arm_post_final_shared_retained_route_same_route_hold(
            step_index=int(state.step_index),
        )
        self.post_final_shared_probe_continuity_ticket_issue_count += 1
        self.post_final_shared_probe_continuity_ticket_consume_count += 1
        self.post_final_shared_probe_continuity_ticket_success_count += 1
        self.last_post_final_shared_probe_continuity_ticket_issued = True
        self.last_post_final_shared_probe_continuity_ticket_consumed = True
        self.last_post_final_shared_probe_continuity_ticket_success = True
        anchor_component_id = str(anchor.get("component_id", "") or "")
        anchor_anchor_key = str(anchor.get("anchor_key", "") or "")
        target_component_id = str(
            anchor_component_id
            or (local_target or {}).get("component_id", "")
            or (selected_target_summary.component_id if selected_target_summary is not None else "")
        )
        target_anchor_key = str(
            anchor_anchor_key
            or (
                self._anchor_key(level_number=state.level_number, component=local_target)
                if local_target
                else (selected_target_summary.anchor_key if selected_target_summary is not None else "")
            )
        )
        if target_component_id:
            self.target_blacklist.pop(target_component_id, None)
        if target_anchor_key:
            self.target_anchor_blacklist.pop(target_anchor_key, None)
        return True

    def _record_post_final_shared_after_exit_same_route_anchor_event(
        self,
        *,
        step_index: int,
    ) -> None:
        normalized_step = int(step_index)
        if int(self.last_post_final_shared_after_exit_same_route_anchor_event_step_idx or -10_000) == normalized_step:
            return
        self.last_post_final_shared_after_exit_same_route_anchor_event_step_idx = normalized_step
        self.post_final_shared_after_exit_same_route_anchor_event_count += 1
        anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
        if anchor:
            anchor["last_same_route_event_step_idx"] = normalized_step
            anchor["same_route_event_count"] = int(anchor.get("same_route_event_count", 0) or 0) + 1
            self.last_post_final_shared_retained_route_anchor = anchor

    def _maybe_apply_post_final_shared_after_exit_probe_continuity_postselect(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any] | None = None,
        selected_target_summary: SelectedTargetSummary | None = None,
        effective_local_contract_source: str | None = None,
        effective_local_contract_component_id: str | None = None,
        effective_local_contract_anchor: str | None = None,
    ) -> None:
        if self._post_final_shared_active():
            return
        if not self._post_final_shared_retained_route_anchor_active(step_index=int(state.step_index)):
            return
        current_selected_target_summary = (
            selected_target_summary
            if selected_target_summary is not None
            else self._last_selected_target_summary_object()
        )
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target=dict(local_target or {}),
                selected_target_summary=current_selected_target_summary,
                target_viability_reason=str(getattr(state, "current_target_viability_reason", "") or ""),
                target_viability_drop_reason=str(
                    getattr(state, "current_target_viability_drop_reason", "") or ""
                ),
                effective_local_contract_source=effective_local_contract_source,
                effective_local_contract_component_id=effective_local_contract_component_id,
                effective_local_contract_anchor=effective_local_contract_anchor,
            )
        )
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(
            late_exit_class or ""
        )
        self.last_post_final_shared_after_exit_same_route_anchor = bool(same_route)
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            float(continuity_score or 0.0),
            3,
        )
        if late_exit_class == "recoverable_exhaustion" and same_route:
            self._record_post_final_shared_after_exit_same_route_anchor_event(
                step_index=int(state.step_index),
            )
        if late_exit_class != "recoverable_exhaustion" or not same_route:
            return
        self._apply_post_final_shared_probe_continuity_from_retained_anchor(
            state=state,
            local_target=dict(local_target or {}),
            selected_target_summary=current_selected_target_summary,
        )

    def _maybe_finalize_post_final_shared_after_exit_same_route_with_finalized_contract(
        self,
        *,
        state: ECAState,
        local_target: dict[str, Any] | None = None,
        selected_target_summary: SelectedTargetSummary | None = None,
        current_local_target_summary: str = "",
    ) -> None:
        if self._post_final_shared_active():
            return
        if not self._post_final_shared_retained_route_anchor_active(step_index=int(state.step_index)):
            return
        late_exit_class, same_route, continuity_score = (
            self._classify_post_final_shared_after_exit_psa_late_exit_class_for_live(
                state=state,
                local_target=dict(local_target or {}),
                selected_target_summary=selected_target_summary,
                target_viability_reason=str(getattr(state, "current_target_viability_reason", "") or ""),
                target_viability_drop_reason=str(
                    getattr(state, "current_target_viability_drop_reason", "") or ""
                ),
                effective_local_contract_source=str(
                    self.last_effective_local_contract_source or ""
                ),
                effective_local_contract_component_id=str(
                    self.last_effective_local_contract_component_id or ""
                ),
                effective_local_contract_anchor=str(
                    self.last_effective_local_contract_anchor or ""
                ),
            )
        )
        if not same_route:
            anchor = dict(self.last_post_final_shared_retained_route_anchor or {})
            anchor_component_id = str(anchor.get("component_id", "") or "")
            effective_source = str(self.last_effective_local_contract_source or "")
            current_summary_text = str(current_local_target_summary or "")
            if (
                anchor_component_id
                and effective_source
                in {
                    self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_SELECTED_TARGET,
                    self.EFFECTIVE_LOCAL_CONTRACT_SOURCE_PROTECTED_HEDGE,
                }
                and anchor_component_id in current_summary_text
            ):
                same_route = True
                continuity_score = max(float(continuity_score or 0.0), 0.5)
                if not late_exit_class and str(getattr(state, "current_target_viability_drop_reason", "") or "") in {
                    "target_move_probe_exhausted",
                    "target_family_probe_exhausted",
                    "fresh_target_minimal_probe_exhausted",
                }:
                    late_exit_class = "recoverable_exhaustion"
        self.last_post_final_shared_after_exit_psa_late_exit_class = str(
            late_exit_class or self.last_post_final_shared_after_exit_psa_late_exit_class or ""
        )
        self.last_post_final_shared_after_exit_same_route_anchor = bool(
            self.last_post_final_shared_after_exit_same_route_anchor or same_route
        )
        self.last_post_final_shared_after_exit_anchor_continuity_score = round(
            max(
                float(self.last_post_final_shared_after_exit_anchor_continuity_score or 0.0),
                float(continuity_score or 0.0),
            ),
            3,
        )
        if late_exit_class == "recoverable_exhaustion" and same_route:
            self._record_post_final_shared_after_exit_same_route_anchor_event(
                step_index=int(state.step_index),
            )
            if not bool((self.last_post_final_shared_retained_route_anchor or {}).get("refresh_used", False)):
                self._apply_post_final_shared_probe_continuity_from_retained_anchor(
                    state=state,
                    local_target=dict(local_target or {}),
                    selected_target_summary=selected_target_summary,
                )

    def _post_final_shared_durable_continuation_ready(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        current_target_viability_reason: str = "",
        current_target_viability_drop_reason: str = "",
    ) -> bool:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item or not self._post_final_shared_active(item):
            return False
        if bool(item.get("post_final_shared_durable_continuation_promotion_used", False)):
            return False
        effective_summary = self._post_final_shared_effective_route_summary(
            contract=item,
            selected_target_summary=selected_target_summary,
            step_index=int(state.step_index),
        )
        if effective_summary is None:
            return False
        if not self._protected_hedge_matches_selected_target(
            selected_target_summary=effective_summary,
            contract=item,
        ):
            return False
        viable_drop_reason = str(current_target_viability_drop_reason or "")
        viable_reason = str(current_target_viability_reason or "")
        if viable_drop_reason not in {
            "target_move_probe_exhausted",
            "target_family_probe_exhausted",
            "fresh_target_minimal_probe_exhausted",
        } and viable_reason not in {
            "psa_anchor_locked_dead",
            "psa_sweep_dead",
            "psa_dead_end",
        }:
            return False
        recent_nonempty_selected_target = self._post_final_shared_recent_nonempty_selected_target(
            contract=item,
            step_index=int(state.step_index),
        )
        same_contract_stable_streak = int(
            item.get("post_final_shared_same_contract_stable_streak", 0) or 0
        )
        queue_exhausted_streak = int(
            item.get("post_final_shared_queue_exhausted_streak", 0) or 0
        )
        if (
            same_contract_stable_streak
            < self.TARGET_POST_FINAL_SHARED_DURABLE_CONTINUATION_MIN_STABLE_STREAK
            and queue_exhausted_streak
            < self.TARGET_POST_FINAL_SHARED_DURABLE_CONTINUATION_MIN_QUEUE_STREAK
            and not recent_nonempty_selected_target
            and not self._post_final_shared_recent_rerank_support(
                contract=item,
                step_index=int(state.step_index),
            )
        ):
            return False
        return True

    def _apply_post_final_shared_durable_continuation_promotion(
        self,
        *,
        contract: dict[str, Any] | None,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        current_target_viability_reason: str = "",
        current_target_viability_drop_reason: str = "",
    ) -> None:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item:
            return
        effective_summary = self._post_final_shared_effective_route_summary(
            contract=item,
            selected_target_summary=selected_target_summary,
            step_index=int(state.step_index),
        )
        effective_step_index = int(state.step_index)
        item["post_final_shared_durable_continuation_promotion_used"] = True
        item["post_final_shared_last_durable_continuation_promotion_step_idx"] = effective_step_index
        self.last_protected_hedge_contract = item
        self.post_final_shared_durable_continuation_promotion_count += 1
        self.last_post_final_shared_durable_continuation_promoted = True

        component_id = str(
            (
                effective_summary.component_id
                if effective_summary is not None
                else ""
            )
            or item.get("component_id", "")
            or ""
        )
        anchor_key = str(
            (
                effective_summary.anchor_key
                if effective_summary is not None
                else ""
            )
            or self._protected_hedge_contract_key(item)
            or ""
        )
        if component_id:
            self.target_blacklist.pop(component_id, None)
        if anchor_key:
            self.target_anchor_blacklist.pop(anchor_key, None)
        if component_id:
            self._set_target_psa_state(
                component_id,
                state_name=self.TARGET_PSA_STATE_VERIFY_ONCE,
                verify_budget=1,
                psa_reason=str(
                    current_target_viability_reason
                    or current_target_viability_drop_reason
                    or "post_final_shared_durable_continuation"
                ),
                viability_score=0.0,
                click_banned=False,
                step_idx=effective_step_index,
                expires_at=effective_step_index + 1,
            )
        self._issue_or_refresh_post_final_shared_retained_route_anchor(
            contract=item,
            state=state,
            selected_target_summary=effective_summary,
            current_target_viability_reason=current_target_viability_reason,
            current_target_viability_drop_reason=current_target_viability_drop_reason,
        )
        self.post_final_shared_probe_refresh_count += 1
        self.last_post_final_shared_probe_refresh_applied = True

    def _enter_post_final_shared_tail(
        self,
        *,
        contract: dict[str, Any],
        step_index: int | None = None,
        reason: str = "",
    ) -> None:
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        contract["post_final_shared_active"] = True
        contract["post_final_shared_entered_step_idx"] = effective_step_index
        contract["post_final_shared_entry_forced_packet"] = bool(
            contract.get("post_final_hold_forced_packet_offered", False)
        )
        contract["post_final_shared_forced_rerank_offered"] = False
        contract["post_final_shared_delayed_reclaim_used"] = False
        contract["post_final_shared_first_visible_psa_rearm_used"] = False
        contract["post_final_shared_durable_continuation_promotion_used"] = False
        contract["post_final_shared_last_durable_continuation_promotion_step_idx"] = -10_000
        contract["post_final_shared_anchor_cooldown_grace_used"] = False
        contract["post_final_shared_entry_ticket_expires_turn"] = (
            effective_step_index + self.TARGET_POST_FINAL_SHARED_ENTRY_TICKET_TTL_STEPS
        )
        contract["post_final_shared_entry_ticket_used"] = False
        contract["post_final_shared_last_rerank_pass_step_idx"] = -10_000
        contract["post_final_shared_queue_exhausted_streak"] = 0
        contract["post_final_shared_last_queue_exhausted_step_idx"] = -10_000
        contract["post_final_shared_same_contract_stable_streak"] = 0
        contract["post_final_shared_last_same_contract_stable_step_idx"] = -10_000
        contract["post_final_shared_last_dead_tail_pressure_step_idx"] = -10_000
        contract["post_final_shared_best_live_escape_candidate_count"] = 0
        contract["post_final_shared_best_escape_candidate_score"] = 0.0
        contract["post_final_shared_best_escape_candidate_threshold_gap"] = 0.0
        self.last_post_final_shared_retained_route_anchor = None
        self.current_post_final_shared_entry_step_idx = effective_step_index
        self.current_post_final_shared_entry_reason = str(reason or "").strip()
        self._maybe_open_pending_shared_tail_sample_on_post_final_shared_entry(
            contract=contract,
            step_index=effective_step_index,
            reason=self.current_post_final_shared_entry_reason,
        )
        self.current_post_final_shared_pending_sample_present_on_entry = (
            self._pending_shared_tail_transition_sample_present_for_level(
                level_idx=int(self.last_state.level_number if self.last_state is not None else -1)
            )
        )
        self.current_post_final_shared_first_visible_step_seen = False
        self.current_post_final_shared_synthetic_pending_sample_used = False
        self._record_pending_shared_tail_sample_present_on_post_final_shared_entry(
            present=self.current_post_final_shared_pending_sample_present_on_entry,
        )
        self._reassert_protected_hedge_visibility_hysteresis(
            contract=contract,
            step_index=effective_step_index,
        )
        self.post_final_shared_entry_ticket_issue_count += 1
        self.post_final_shared_entry_count += 1

    def _record_post_final_shared_exit_reason(self, reason: str) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        self.post_final_shared_exit_reason_histogram[normalized_reason] = int(
            self.post_final_shared_exit_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1

    def _record_post_final_shared_rearm_block_reason(self, reason: str) -> None:
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        self.post_final_shared_rearm_block_reason_histogram[normalized_reason] = int(
            self.post_final_shared_rearm_block_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1
        self.last_post_final_shared_rearm_block_reason = normalized_reason

    def _record_post_final_shared_rearm_block_reasons(
        self,
        reasons: list[str] | tuple[str, ...],
        *,
        primary_reason: str = "",
    ) -> None:
        normalized_reasons: list[str] = []
        seen_reasons: set[str] = set()
        for reason in reasons:
            normalized_reason = str(reason or "").strip()
            if not normalized_reason or normalized_reason in seen_reasons:
                continue
            normalized_reasons.append(normalized_reason)
            seen_reasons.add(normalized_reason)
        if not normalized_reasons:
            return
        for reason in normalized_reasons:
            self.post_final_shared_rearm_block_reason_histogram[reason] = int(
                self.post_final_shared_rearm_block_reason_histogram.get(reason, 0) or 0
            ) + 1
        chosen_primary_reason = str(primary_reason or "").strip()
        if not chosen_primary_reason or chosen_primary_reason not in seen_reasons:
            chosen_primary_reason = normalized_reasons[0]
        self.last_post_final_shared_rearm_block_reason = chosen_primary_reason

    def _record_post_final_shared_contract_progress_signal(self, signal: str) -> None:
        normalized_signal = str(signal or "").strip()
        if not normalized_signal:
            return
        self.post_final_shared_contract_progress_signal_histogram[normalized_signal] = int(
            self.post_final_shared_contract_progress_signal_histogram.get(normalized_signal, 0) or 0
        ) + 1
        self.last_post_final_shared_contract_progress_signal = normalized_signal

    def _record_post_final_shared_contract_progress_signals(
        self,
        signals: list[str] | tuple[str, ...],
        *,
        primary_signal: str = "",
    ) -> None:
        normalized_signals: list[str] = []
        seen_signals: set[str] = set()
        for signal in signals:
            normalized_signal = str(signal or "").strip()
            if not normalized_signal or normalized_signal in seen_signals:
                continue
            normalized_signals.append(normalized_signal)
            seen_signals.add(normalized_signal)
        if not normalized_signals:
            return
        for signal in normalized_signals:
            self.post_final_shared_contract_progress_signal_histogram[signal] = int(
                self.post_final_shared_contract_progress_signal_histogram.get(signal, 0) or 0
            ) + 1
        chosen_primary_signal = str(primary_signal or "").strip()
        if not chosen_primary_signal or chosen_primary_signal not in seen_signals:
            chosen_primary_signal = normalized_signals[0]
        self.last_post_final_shared_contract_progress_signal = chosen_primary_signal

    def _mark_post_final_shared_weak_progress_only(self) -> None:
        self.post_final_shared_weak_progress_only_count += 1

    def _record_post_final_shared_weak_motion_signals(
        self,
        signals: list[str] | tuple[str, ...],
        *,
        step_index: int | None = None,
    ) -> None:
        normalized_signals: list[str] = []
        seen_signals: set[str] = set()
        for signal in signals:
            normalized_signal = str(signal or "").strip()
            if not normalized_signal or normalized_signal in seen_signals:
                continue
            normalized_signals.append(normalized_signal)
            seen_signals.add(normalized_signal)
        if not normalized_signals:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        contract = dict(self.last_protected_hedge_contract or {})
        last_signal_step_idx = int(
            contract.get("post_final_shared_last_weak_motion_signal_step_idx", -10_000) or -10_000
        )
        already_recorded = {
            str(item or "")
            for item in (
                contract.get("post_final_shared_last_weak_motion_signals", [])
                if last_signal_step_idx == effective_step_index
                else []
            )
        }
        updated_signals = set(already_recorded)
        for signal in normalized_signals:
            if signal in updated_signals:
                continue
            self.post_final_shared_weak_motion_signal_histogram[signal] = int(
                self.post_final_shared_weak_motion_signal_histogram.get(signal, 0) or 0
            ) + 1
            updated_signals.add(signal)
        contract["post_final_shared_last_weak_motion_signal_step_idx"] = effective_step_index
        contract["post_final_shared_last_weak_motion_signals"] = sorted(updated_signals)
        self.last_protected_hedge_contract = contract

    def _refresh_post_final_shared_step_streaks(
        self,
        *,
        previous_step_index: int,
    ) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        if not self._post_final_shared_active(contract):
            contract["post_final_shared_queue_exhausted_streak"] = 0
            contract["post_final_shared_same_contract_stable_streak"] = 0
            self.last_protected_hedge_contract = contract
            return
        effective_previous_step = int(previous_step_index)
        if int(contract.get("post_final_shared_last_queue_exhausted_step_idx", -10_000) or -10_000) != effective_previous_step:
            contract["post_final_shared_queue_exhausted_streak"] = 0
        if int(contract.get("post_final_shared_last_same_contract_stable_step_idx", -10_000) or -10_000) != effective_previous_step:
            contract["post_final_shared_same_contract_stable_streak"] = 0
        self.last_protected_hedge_contract = contract

    def _post_final_shared_dead_tail_pressure_rising(
        self,
        *,
        dead_tail_ratio: float,
        dead_tail_ratio_delta: float,
        live_escape_candidate_count: int,
    ) -> bool:
        return (
            float(dead_tail_ratio or 0.0) >= self.TARGET_PROTECTED_HEDGE_RECLAIM_DEAD_TAIL_RATIO
            and float(dead_tail_ratio_delta or 0.0) >= self.TARGET_PROTECTED_HEDGE_RECLAIM_DEAD_TAIL_DELTA
            and int(live_escape_candidate_count or 0) <= 1
        )

    def _mark_post_final_shared_dead_tail_pressure(
        self,
        *,
        step_index: int,
        dead_tail_ratio: float,
        dead_tail_ratio_delta: float,
        live_escape_candidate_count: int,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._post_final_shared_active(contract):
            return False
        if not self._post_final_shared_dead_tail_pressure_rising(
            dead_tail_ratio=dead_tail_ratio,
            dead_tail_ratio_delta=dead_tail_ratio_delta,
            live_escape_candidate_count=live_escape_candidate_count,
        ):
            return False
        effective_step_index = int(step_index)
        if int(contract.get("post_final_shared_last_dead_tail_pressure_step_idx", -10_000) or -10_000) != effective_step_index:
            contract["post_final_shared_last_dead_tail_pressure_step_idx"] = effective_step_index
            self.last_protected_hedge_contract = contract
        return True

    def _post_final_shared_mixed_churn_ready(
        self,
        *,
        contract: dict[str, Any],
        step_index: int,
    ) -> bool:
        effective_step_index = int(step_index)
        window_start = effective_step_index - self.TARGET_POST_FINAL_SHARED_MIXED_CHURN_WINDOW_STEPS + 1
        category_credit = 0
        credit_step_idxs: set[int] = set()
        for field_name in (
            "post_final_shared_last_queue_exhausted_step_idx",
            "post_final_shared_last_same_contract_stable_step_idx",
            "post_final_shared_last_dead_tail_pressure_step_idx",
            "post_final_shared_last_rerank_pass_step_idx",
        ):
            event_step_idx = int(contract.get(field_name, -10_000) or -10_000)
            if event_step_idx < window_start:
                continue
            category_credit += 1
            credit_step_idxs.add(event_step_idx)
        distinct_credit = len(credit_step_idxs)
        self.post_final_shared_distinct_churn_credit_max = max(
            int(self.post_final_shared_distinct_churn_credit_max or 0),
            int(distinct_credit),
        )
        self.last_post_final_shared_distinct_churn_credit = max(
            int(self.last_post_final_shared_distinct_churn_credit or 0),
            int(distinct_credit),
        )
        ready = (
            category_credit >= self.TARGET_POST_FINAL_SHARED_MIXED_CHURN_MIN_CREDIT
            and distinct_credit >= self.TARGET_POST_FINAL_SHARED_MIXED_CHURN_MIN_CREDIT
        )
        updated_contract = dict(self.last_protected_hedge_contract or contract)
        if updated_contract:
            updated_contract["post_final_shared_last_mixed_churn_credit_step_idx"] = effective_step_index
            updated_contract["post_final_shared_last_mixed_churn_distinct_credit"] = int(distinct_credit)
            prior_hit_step_idx = int(
                updated_contract.get("post_final_shared_last_mixed_churn_window_hit_step_idx", -10_000)
                or -10_000
            )
            if ready and prior_hit_step_idx != effective_step_index:
                self.post_final_shared_mixed_churn_window_hit_count += 1
                updated_contract["post_final_shared_last_mixed_churn_window_hit_step_idx"] = (
                    effective_step_index
                )
            self.last_protected_hedge_contract = updated_contract
        if ready:
            self.last_post_final_shared_mixed_churn_window_hit = True
        return ready

    def _evaluate_post_final_shared_contract_progress(
        self,
        *,
        state: ECAState,
        selected_target_summary: SelectedTargetSummary | None,
        live_escape_candidate_count: int,
        best_escape_candidate_score: float,
        best_escape_candidate_threshold_gap: float,
        current_target_viability_reason: str = "",
        current_target_viability_drop_reason: str = "",
    ) -> tuple[bool, str]:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._post_final_shared_active(contract):
            return False, ""
        self._mark_post_final_shared_nonempty_selected_target(
            contract=contract,
            step_index=int(state.step_index),
            selected_target_summary=selected_target_summary,
        )
        contract = dict(self.last_protected_hedge_contract or contract)
        previous_live_escape_count = int(
            contract.get("post_final_shared_best_live_escape_candidate_count", 0) or 0
        )
        previous_escape_score = float(
            contract.get("post_final_shared_best_escape_candidate_score", 0.0) or 0.0
        )
        previous_escape_gap = float(
            contract.get("post_final_shared_best_escape_candidate_threshold_gap", 0.0) or 0.0
        )
        normalized_live_escape_count = max(0, int(live_escape_candidate_count or 0))
        normalized_escape_score = float(best_escape_candidate_score or 0.0)
        normalized_escape_gap = float(best_escape_candidate_threshold_gap or 0.0)
        normalized_score_delta = float(state.score_delta or 0.0)
        escape_gap_delta = normalized_escape_gap - previous_escape_gap
        escape_score_delta = normalized_escape_score - previous_escape_score
        progress_signals: list[str] = []
        weak_motion_signals: list[str] = []
        if normalized_score_delta > self.TARGET_POST_FINAL_SHARED_SCORE_DELTA_PROGRESS_EPS:
            progress_signals.append("score_delta")
        if normalized_live_escape_count > previous_live_escape_count:
            progress_signals.append("live_escape_candidate_count_increased")
        if escape_gap_delta > self.TARGET_POST_FINAL_SHARED_ESCAPE_GAP_IMPROVEMENT_EPS:
            progress_signals.append("escape_gap_improved")
        if escape_score_delta > self.TARGET_POST_FINAL_SHARED_ESCAPE_SCORE_IMPROVEMENT_EPS:
            progress_signals.append("escape_best_score_improved")
        progress = bool(progress_signals)

        if not progress:
            effective_route_summary = self._post_final_shared_effective_route_summary(
                contract=contract,
                selected_target_summary=selected_target_summary,
                step_index=int(state.step_index),
            )
            if (
                effective_route_summary
                and str(
                    effective_route_summary.component_id
                    or effective_route_summary.candidate_id
                    or ""
                )
            ):
                weak_motion_signals.append("selected_target_admitted_only")
            if 0.0 < normalized_score_delta <= self.TARGET_POST_FINAL_SHARED_SCORE_DELTA_PROGRESS_EPS:
                weak_motion_signals.append("micro_score_delta_only")
            if 0.0 < escape_gap_delta <= self.TARGET_POST_FINAL_SHARED_ESCAPE_GAP_IMPROVEMENT_EPS:
                weak_motion_signals.append("micro_escape_gap_shift_only")
            if 0.0 < escape_score_delta <= self.TARGET_POST_FINAL_SHARED_ESCAPE_SCORE_IMPROVEMENT_EPS:
                weak_motion_signals.append("micro_escape_score_shift_only")
            if self._post_final_shared_durable_continuation_ready(
                contract=contract,
                state=state,
                selected_target_summary=selected_target_summary,
                current_target_viability_reason=current_target_viability_reason,
                current_target_viability_drop_reason=current_target_viability_drop_reason,
            ):
                self._apply_post_final_shared_durable_continuation_promotion(
                    contract=contract,
                    state=state,
                    selected_target_summary=selected_target_summary,
                    current_target_viability_reason=current_target_viability_reason,
                    current_target_viability_drop_reason=current_target_viability_drop_reason,
                )
                progress_signals.append("durable_continuation_promotion")
                progress = True
            elif weak_motion_signals:
                self._mark_post_final_shared_weak_progress_only()
                self._record_post_final_shared_weak_motion_signals(
                    weak_motion_signals,
                    step_index=int(state.step_index),
                )

        contract["post_final_shared_best_live_escape_candidate_count"] = max(
            previous_live_escape_count,
            normalized_live_escape_count,
        )
        contract["post_final_shared_best_escape_candidate_score"] = max(
            previous_escape_score,
            normalized_escape_score,
        )
        contract["post_final_shared_best_escape_candidate_threshold_gap"] = max(
            previous_escape_gap,
            normalized_escape_gap,
        )
        self.last_protected_hedge_contract = contract
        if progress_signals:
            self._record_post_final_shared_contract_progress_signals(
                progress_signals,
                primary_signal=progress_signals[0],
            )
            return True, progress_signals[0]
        non_progress_signals = [*weak_motion_signals, "contract_local_churn"]
        primary_signal = weak_motion_signals[0] if weak_motion_signals else "contract_local_churn"
        self._record_post_final_shared_contract_progress_signals(
            non_progress_signals,
            primary_signal=primary_signal,
        )
        return False, primary_signal

    def _exit_post_final_shared_tail(
        self,
        *,
        reason: str,
        step_index: int | None = None,
        contract: dict[str, Any] | None = None,
    ) -> None:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item or not bool(item.get("post_final_shared_active", False)):
            return
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        entered_step_idx = int(item.get("post_final_shared_entered_step_idx", -1) or -1)
        if entered_step_idx >= 0:
            self.post_final_shared_exit_turn_total += max(0, effective_step_index - entered_step_idx)
            self.post_final_shared_exit_turn_count += 1
        item["post_final_shared_active"] = False
        item["post_final_shared_entered_step_idx"] = -1
        item["post_final_shared_entry_ticket_expires_turn"] = -1
        item["post_final_shared_entry_ticket_used"] = True
        self.current_post_final_shared_entry_step_idx = -1
        self.current_post_final_shared_entry_reason = ""
        self.current_post_final_shared_pending_sample_present_on_entry = False
        self.current_post_final_shared_first_visible_step_seen = False
        self.current_post_final_shared_synthetic_pending_sample_used = False
        self._record_post_final_shared_exit_reason(normalized_reason)
        self.last_post_final_shared_exit_reason = normalized_reason
        self.last_post_final_shared_exit_step_idx = effective_step_index
        if (
            normalized_reason.startswith("shared_post_final_shared_")
            and normalized_reason.endswith("_to_reclaimable")
        ):
            self._arm_post_final_shared_retained_route_anchor_after_exit(
                step_index=effective_step_index,
            )
            self._issue_post_final_shared_continuation_ticket(
                contract=item,
                source=normalized_reason,
                step_index=effective_step_index,
            )
        if contract is None:
            self.last_protected_hedge_contract = item
        else:
            contract.clear()
            contract.update(item)

    def _mark_post_final_hold_carryover_terminalizing_suppressed(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if int(contract.get("post_final_hold_last_terminalizing_suppressed_step_idx", -10_000) or -10_000) != effective_step_index:
            self.post_final_hold_carryover_terminalizing_suppressed_count += 1
            contract["post_final_hold_last_terminalizing_suppressed_step_idx"] = effective_step_index
            self.last_protected_hedge_contract = contract
        self.last_post_final_hold_carryover_terminalizing_suppressed = True

    def _mark_stale_protected_hedge_contract_render(
        self,
        *,
        step_index: int | None = None,
    ) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if int(contract.get("stale_protected_hedge_render_step_idx", -10_000) or -10_000) != effective_step_index:
            self.stale_protected_hedge_contract_render_count += 1
            contract["stale_protected_hedge_render_step_idx"] = effective_step_index
            self.last_protected_hedge_contract = contract
        self.last_stale_protected_hedge_contract_render = True

    def _mark_post_final_hold_survived_one_step_if_needed(self, *, state: ECAState) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        if (
            self._protected_hedge_runtime_claim_state(contract)
            != self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD
        ):
            return
        entered_step_idx = int(contract.get("post_final_reclaim_hold_entered_step_idx", -1) or -1)
        if entered_step_idx < 0 or int(state.step_index) <= entered_step_idx:
            return
        if bool(contract.get("post_final_hold_survived_one_step_counted", False)):
            self.last_post_final_hold_survived_one_step = True
            return
        contract["post_final_hold_survived_one_step_counted"] = True
        self.last_protected_hedge_contract = contract
        self.post_final_hold_survived_one_step_count += 1
        self.last_post_final_hold_survived_one_step = True

    def _should_force_post_final_hold_runtime_packet_after_one_step(
        self,
        *,
        contract: dict[str, Any] | None = None,
    ) -> bool:
        if not bool(self.config.force_post_final_hold_runtime_packet_after_one_step):
            return False
        item = dict(contract if contract is not None else self.last_protected_hedge_contract or {})
        if not item:
            return False
        if (
            self._protected_hedge_runtime_claim_state(item)
            != self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD
        ):
            return False
        if not self._post_final_reclaim_hold_ready_for_packet(item):
            return False
        if not bool(item.get("post_final_hold_survived_one_step_counted", False)):
            return False
        if bool(item.get("post_final_reclaim_hold_runtime_packet_pending", False)):
            return False
        if bool(item.get("post_final_reclaim_hold_runtime_packet_used", False)):
            return False
        if bool(item.get("post_final_hold_forced_packet_offered", False)):
            return False
        return True

    def _post_reclaim_hold_ready_source(self, contract: dict[str, Any] | None = None) -> str:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item:
            return ""
        if self._protected_hedge_runtime_claim_state(item) != self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD:
            return ""
        if bool(item.get("post_reclaim_hold_stable_turn_used", False)):
            return "stable_turn"
        if bool(item.get("post_reclaim_hold_runtime_confirmed", False)):
            return "runtime_confirm"
        if self._reclaim_ticket_matches_contract(item):
            return "reclaim_ticket"
        return ""

    def _post_reclaim_hold_ready_for_final_reclaim(self, contract: dict[str, Any] | None = None) -> bool:
        return bool(self._post_reclaim_hold_ready_source(contract))

    def _record_runtime_confirm_result(
        self,
        *,
        stage: str,
        success: bool,
        block_reason: str = "",
    ) -> None:
        normalized_stage = str(stage or "").strip()
        normalized_reason = str(block_reason or "").strip()
        if normalized_stage == "reclaimable":
            self.reclaimable_runtime_confirm_attempt_count += 1
            if success:
                self.reclaimable_runtime_confirm_success_count += 1
                return
            if normalized_reason:
                self.reclaimable_runtime_confirm_block_reason_histogram[normalized_reason] = int(
                    self.reclaimable_runtime_confirm_block_reason_histogram.get(normalized_reason, 0) or 0
                ) + 1
            return
        if normalized_stage == "post_reclaim_hold":
            self.post_reclaim_hold_runtime_confirm_attempt_count += 1
            if success:
                self.post_reclaim_hold_runtime_confirm_success_count += 1
                return
            if normalized_reason:
                self.post_reclaim_hold_runtime_confirm_block_reason_histogram[normalized_reason] = int(
                    self.post_reclaim_hold_runtime_confirm_block_reason_histogram.get(normalized_reason, 0) or 0
                ) + 1
            return
        if normalized_stage == "post_final_reclaim_hold":
            self.post_final_reclaim_hold_runtime_confirm_attempt_count += 1
            if success:
                self.post_final_reclaim_hold_runtime_confirm_success_count += 1
                return
            if normalized_reason:
                self.post_final_reclaim_hold_runtime_confirm_block_reason_histogram[normalized_reason] = int(
                    self.post_final_reclaim_hold_runtime_confirm_block_reason_histogram.get(normalized_reason, 0) or 0
                ) + 1
            return

    def _confirm_reclaim_success_runtime_if_needed(self, *, state: ECAState) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="no_contract",
            )
            return False
        if not self._protected_hedge_contract_active(contract):
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="contract_inactive",
            )
            return False
        if self._protected_hedge_runtime_claim_state(contract) != self.PROTECTED_HEDGE_CLAIM_STATE_RECLAIMABLE:
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="wrong_claim_state",
            )
            return False
        last_transition_step_idx = int(contract.get("runtime_claim_last_transition_step_idx", -1) or -1)
        if last_transition_step_idx < 0 or int(state.step_index) <= last_transition_step_idx:
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="same_step_not_survived",
            )
            return False
        if not bool(self.last_protected_hedge_visible or self._protected_hedge_contract_visible(contract)):
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="protected_hedge_not_visible",
            )
            return False
        if bool(self.runtime_micro_probe_event_pending):
            self._record_runtime_confirm_result(
                stage="reclaimable",
                success=False,
                block_reason="runtime_probe_pending",
            )
            return False
        if self._attempt_protected_hedge_post_reclaim_hold_entry(step_index=int(state.step_index)):
            self._record_runtime_confirm_result(stage="reclaimable", success=True)
            return True
        block_reason = self._post_reclaim_hold_entry_block_reason(
            contract=self.last_protected_hedge_contract
        )
        self._record_runtime_confirm_result(
            stage="reclaimable",
            success=False,
            block_reason=block_reason or "hold_entry_blocked",
        )
        return False

    def _confirm_post_reclaim_hold_runtime_if_needed(self, *, state: ECAState) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="no_contract",
            )
            return False
        if not self._protected_hedge_contract_active(contract):
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="contract_inactive",
            )
            return False
        if self._protected_hedge_runtime_claim_state(contract) != self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD:
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="wrong_claim_state",
            )
            return False
        if bool(contract.get("post_reclaim_hold_stable_turn_used", False)):
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="stable_turn_used",
            )
            return False
        if bool(contract.get("post_reclaim_hold_runtime_confirmed", False)):
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="already_confirmed",
            )
            return False
        entered_step_idx = int(contract.get("post_reclaim_hold_entered_step_idx", -1) or -1)
        if entered_step_idx < 0 or int(state.step_index) <= entered_step_idx:
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="same_step_not_survived",
            )
            return False
        if not bool(self.last_protected_hedge_visible or self._protected_hedge_contract_visible(contract)):
            self._record_runtime_confirm_result(
                stage="post_reclaim_hold",
                success=False,
                block_reason="protected_hedge_not_visible",
            )
            return False
        contract["post_reclaim_hold_runtime_confirmed"] = True
        contract["post_reclaim_hold_runtime_confirm_step_idx"] = int(state.step_index)
        self.last_protected_hedge_contract = contract
        self._issue_reclaim_ticket(
            contract=contract,
            source="runtime_confirm",
            step_index=int(state.step_index),
        )
        self._record_runtime_confirm_result(stage="post_reclaim_hold", success=True)
        return True

    def _post_final_reclaim_hold_ready_source(self, contract: dict[str, Any] | None = None) -> str:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item:
            return ""
        if self._protected_hedge_runtime_claim_state(item) != self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD:
            return ""
        if bool(item.get("post_final_reclaim_hold_stable_turn_used", False)):
            return "stable_turn"
        if bool(item.get("post_final_reclaim_hold_runtime_confirmed", False)):
            return "runtime_confirm"
        if self._post_final_packet_ticket_matches_contract(item):
            return "packet_ticket"
        return ""

    def _post_final_reclaim_hold_ready_for_packet(self, contract: dict[str, Any] | None = None) -> bool:
        return bool(self._post_final_reclaim_hold_ready_source(contract))

