    def _persist_transition_memory(
        self,
        transition_memory: dict[str, Any],
    ) -> None:
        path = self.transition_memory_path
        if path is None:
            return
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(transition_memory, ensure_ascii=False, indent=2, sort_keys=True),
            encoding="utf-8",
        )

    def _normalize_post_final_shared_block_family(self, reason: str) -> str:
        normalized_reason = str(reason or "").strip().lower()
        if not normalized_reason:
            return ""
        if (
            normalized_reason in {"positive_progress_present", "shared_positive_progress"}
            or "positive_progress" in normalized_reason
        ):
            return "progress"
        if normalized_reason in {
            "effective_contract_not_protected_hedge",
            "shared_contract_drift",
            "same_contract_lost",
        } or "contract_drift" in normalized_reason:
            return "contract_drift"
        if normalized_reason in {
            "queue_streak_below_threshold",
            "stable_streak_below_threshold",
            "shared_churn_streak_below_threshold",
        } or normalized_reason.endswith("_below_threshold"):
            return "below_threshold"
        if normalized_reason in {
            "reclaim_already_used",
            "shared_reclaim_already_used",
        } or "reclaim_already_used" in normalized_reason:
            return "reclaim_already_used"
        return ""

    def _classify_post_final_shared_primary_block_family(self, *, read_class: str) -> str:
        if str(read_class or "") != "reached_no_rearm":
            return "none"
        family_histogram: dict[str, int] = {}
        for reason, count in self.post_final_shared_rearm_block_reason_histogram.items():
            family = self._normalize_post_final_shared_block_family(str(reason or ""))
            if not family:
                continue
            family_histogram[family] = int(family_histogram.get(family, 0) or 0) + int(count or 0)
        if not family_histogram:
            fallback_family = self._normalize_post_final_shared_block_family(
                self.last_post_final_shared_rearm_block_reason
            )
            return fallback_family or "none"
        max_count = max(int(count or 0) for count in family_histogram.values())
        candidates = {
            family
            for family, count in family_histogram.items()
            if int(count or 0) == max_count
        }
        last_family = self._normalize_post_final_shared_block_family(
            self.last_post_final_shared_rearm_block_reason
        )
        if last_family in candidates:
            return last_family
        for family in ("progress", "contract_drift", "below_threshold", "reclaim_already_used"):
            if family in candidates:
                return family
        return sorted(candidates)[0]

    def _evaluate_protected_hedge_reclaim_success_strength(
        self,
        *,
        state: ECAState,
        board_changed: bool,
        score_changed: bool,
        repeated_state: bool,
        claim_rearm_reason: str = "",
    ) -> tuple[bool, str]:
        if not bool(board_changed) or bool(repeated_state):
            return False, "weak_reclaim_result"
        if bool(score_changed):
            return True, "score_changed"
        if int(state.current_state_changed_actions or 0) > 0:
            return True, "current_state_changed_actions"
        if float(state.known_effect_ratio or 0.0) >= 0.25:
            return True, "known_effect_ratio"
        # Late reclaim packets often land after the live target is already terminalizing,
        # so global "known action" counters can stay at zero even when the reclaim
        # produced the exact local board change the hedge contract was waiting for.
        normalized_claim_rearm_reason = str(claim_rearm_reason or "")
        if normalized_claim_rearm_reason in {
            "same_contract_stable_no_change",
            "selected_target_terminalizing",
            "dead_tail_pressure_rising",
            "post_final_shared_stable_churn",
            "post_final_shared_queue_churn",
        }:
            return True, f"contract_continuity:{normalized_claim_rearm_reason}"
        return False, "no_contract_continuity_or_effect_signal"

    def _protected_hedge_reclaim_success_is_strong(
        self,
        *,
        state: ECAState,
        board_changed: bool,
        score_changed: bool,
        repeated_state: bool,
        claim_rearm_reason: str = "",
    ) -> bool:
        strong, _ = self._evaluate_protected_hedge_reclaim_success_strength(
            state=state,
            board_changed=board_changed,
            score_changed=score_changed,
            repeated_state=repeated_state,
            claim_rearm_reason=claim_rearm_reason,
        )
        return bool(strong)

    def _record_protected_hedge_runtime_claim_rearm(
        self,
        *,
        contract: dict[str, Any],
        reason: str,
        step_index: int,
    ) -> None:
        normalized_reason = str(reason or "")
        if not normalized_reason:
            return
        last_reason = str(contract.get("runtime_claim_last_counted_reason", "") or "")
        last_step_index = int(contract.get("runtime_claim_last_counted_step_idx", -10_000) or -10_000)
        if last_reason == normalized_reason and last_step_index == int(step_index):
            return
        self.runtime_claim_rearm_reason_histogram[normalized_reason] = int(
            self.runtime_claim_rearm_reason_histogram.get(normalized_reason, 0) or 0
        ) + 1
        contract["runtime_claim_last_counted_reason"] = normalized_reason
        contract["runtime_claim_last_counted_step_idx"] = int(step_index)
        self.last_protected_hedge_runtime_claim_rearmed = True
        self.last_protected_hedge_runtime_claim_rearm_reason = normalized_reason

    def _arm_protected_hedge_runtime_claim(
        self,
        *,
        reason: str,
        step_index: int | None = None,
        count_as_rearm: bool = False,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED
        contract["runtime_claim_rearm_reason"] = str(reason or "")
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_reclaim_used"] = False
        contract["runtime_probe_budget"] = 1
        self._clear_protected_hedge_runtime_aftercare_fields(contract=contract)
        if count_as_rearm:
            self._record_protected_hedge_runtime_claim_rearm(
                contract=contract,
                reason=str(reason or ""),
                step_index=effective_step_index,
            )
        self.last_protected_hedge_contract = contract
        return True

    def _enter_protected_hedge_post_reclaim_hold(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if (
            self._protected_hedge_runtime_claim_state(contract)
            == self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD
        ):
            return False
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD
        contract["runtime_claim_rearm_reason"] = "successful_reclaim_hold"
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 0
        contract["runtime_reclaim_used"] = True
        contract["successful_reclaim_step_idx"] = effective_step_index
        contract["successful_reclaim_strength"] = "strong"
        contract["successful_reclaim_stable_tail_count"] = 0
        contract["successful_reclaim_queue_exhaustion_count"] = 0
        contract["successful_reclaim_exhausted_counted"] = False
        contract["post_reclaim_hold_entered_step_idx"] = effective_step_index
        contract["post_reclaim_hold_stable_turn_used"] = False
        contract["post_reclaim_hold_stable_turn_step_idx"] = -1
        contract["post_reclaim_hold_runtime_confirmed"] = False
        contract["post_reclaim_hold_runtime_confirm_step_idx"] = -1
        contract["final_reclaimable_entered_step_idx"] = -1
        contract["final_reclaimable_reason"] = ""
        contract["runtime_final_reclaim_used"] = False
        self.last_protected_hedge_contract = contract
        self._reassert_protected_hedge_visibility_hysteresis(
            contract=contract,
            step_index=effective_step_index,
        )
        self.post_reclaim_hold_count += 1
        return True

    def _post_reclaim_hold_entry_block_reason(
        self,
        *,
        contract: dict[str, Any] | None = None,
    ) -> str:
        item = dict(contract if contract is not None else (self.last_protected_hedge_contract or {}))
        if not item:
            return "no_contract"
        if not self._protected_hedge_contract_active(item):
            return "inactive_contract"
        if (
            self._protected_hedge_runtime_claim_state(item)
            == self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD
        ):
            return "already_post_reclaim_hold"
        return ""

    def _attempt_protected_hedge_post_reclaim_hold_entry(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        self.post_reclaim_hold_entry_attempt_count += 1
        block_reason = self._post_reclaim_hold_entry_block_reason()
        if block_reason:
            self._record_post_reclaim_hold_entry_block_reason(block_reason)
            return False
        entered = self._enter_protected_hedge_post_reclaim_hold(step_index=step_index)
        if not entered:
            self._record_post_reclaim_hold_entry_block_reason("unexpected_entry_failure")
            return False
        return True

    def _enter_protected_hedge_post_final_reclaim_hold(
        self,
        *,
        step_index: int | None = None,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if (
            self._protected_hedge_runtime_claim_state(contract)
            == self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD
        ):
            return False
        contract["state"] = self.PROTECTED_HEDGE_STATE_PINNED
        if int(contract.get("visible_from_step_idx", -1) or -1) < 0:
            contract["visible_from_step_idx"] = effective_step_index
        if int(contract.get("pinned_from_step_idx", -1) or -1) < 0:
            contract["pinned_from_step_idx"] = effective_step_index
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_POST_FINAL_RECLAIM_HOLD
        contract["runtime_claim_rearm_reason"] = "successful_final_reclaim_hold"
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 0
        contract["runtime_reclaim_used"] = True
        contract["runtime_final_reclaim_used"] = True
        contract["successful_reclaim_step_idx"] = effective_step_index
        contract["successful_reclaim_strength"] = "final"
        contract["successful_reclaim_stable_tail_count"] = 0
        contract["successful_reclaim_queue_exhaustion_count"] = 0
        contract["successful_reclaim_exhausted_counted"] = False
        contract["post_reclaim_hold_entered_step_idx"] = -1
        contract["post_reclaim_hold_stable_turn_used"] = False
        contract["post_reclaim_hold_stable_turn_step_idx"] = -1
        contract["post_final_reclaim_hold_entered_step_idx"] = effective_step_index
        contract["post_final_reclaim_hold_stable_turn_used"] = False
        contract["post_final_reclaim_hold_stable_turn_step_idx"] = -1
        contract["post_final_reclaim_hold_runtime_confirmed"] = False
        contract["post_final_reclaim_hold_runtime_confirm_step_idx"] = -1
        contract["post_final_reclaim_hold_rendered"] = False
        contract["post_final_reclaim_hold_ignore_inherited_terminalizing"] = True
        contract["post_final_reclaim_hold_runtime_packet_pending"] = False
        contract["post_final_reclaim_hold_runtime_packet_used"] = False
        contract["post_final_hold_survived_one_step_counted"] = False
        contract["post_final_hold_forced_packet_offered"] = False
        contract["post_final_hold_runtime_packet_eligible_step_idx"] = -10_000
        self.last_protected_hedge_contract = contract
        self._reassert_protected_hedge_visibility_hysteresis(
            contract=contract,
            step_index=effective_step_index,
        )
        self.post_final_reclaim_hold_count += 1
        self._issue_post_final_packet_ticket(
            contract=contract,
            source="entry",
            step_index=effective_step_index,
        )
        return True

    def _complete_protected_hedge_post_final_reclaim_hold_to_shared(
        self,
        *,
        step_index: int | None = None,
        reason: str = "stable_success_to_shared",
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        self._record_post_final_hold_exit_before_packet(
            reason=reason,
            step_index=effective_step_index,
            contract=contract,
        )
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_SHARED
        contract["runtime_claim_rearm_reason"] = ""
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 0
        contract["runtime_reclaim_used"] = True
        contract["runtime_final_reclaim_used"] = True
        self._clear_protected_hedge_runtime_aftercare_fields(
            contract=contract,
            preserve_final_reclaim_used=True,
        )
        if str(reason or "") == "runtime_packet_success_to_shared":
            self._enter_post_final_shared_tail(
                contract=contract,
                step_index=effective_step_index,
                reason=reason,
            )
        self.last_protected_hedge_contract = contract
        self.last_protected_hedge_visible = True
        self._record_post_final_reclaim_hold_exit_reason(reason)
        return True

    def _release_protected_hedge_post_final_reclaim_hold(
        self,
        *,
        reason: str,
        step_index: int | None = None,
    ) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        self._record_post_final_hold_exit_before_packet(
            reason=reason,
            step_index=effective_step_index,
            contract=contract,
        )
        self._record_post_final_reclaim_hold_exit_reason(reason)
        self._record_successful_reclaim_exhaustion(
            contract=contract,
            step_index=effective_step_index,
        )
        self._consume_protected_hedge_contract(
            reason=f"post_final_reclaim_hold:{reason}",
            step_index=effective_step_index,
        )

    def _make_protected_hedge_runtime_claim_reclaimable(
        self,
        *,
        reason: str,
        step_index: int | None = None,
        allow_post_final_shared_one_shot: bool = False,
        allow_claimed_bridge: bool = False,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        post_final_shared_one_shot_allowed = bool(
            allow_post_final_shared_one_shot
            and self._post_final_shared_active(contract)
            and not bool(contract.get("post_final_shared_delayed_reclaim_used", False))
        )
        if self._protected_hedge_runtime_reclaim_used(contract) and not post_final_shared_one_shot_allowed:
            return False
        current_claim_state = self._protected_hedge_runtime_claim_state(contract)
        claimed_bridge_allowed = bool(
            allow_claimed_bridge
            and not self._post_final_shared_active(contract)
            and current_claim_state == self.PROTECTED_HEDGE_CLAIM_STATE_CLAIMED
        )
        if (
            current_claim_state != self.PROTECTED_HEDGE_CLAIM_STATE_SHARED
            and not claimed_bridge_allowed
        ):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        normalized_reason = str(reason or "").strip()
        if self._post_final_shared_active(contract):
            self.post_final_shared_runtime_reclaim_rearm_count += 1
            self.last_post_final_shared_runtime_reclaim_rearmed = True
            self._open_shared_tail_transition_sample(
                reason=normalized_reason,
                step_index=effective_step_index,
                contract=contract,
                source="runtime_claim_rearm",
            )
            self._exit_post_final_shared_tail(
                contract=contract,
                reason=f"shared_{normalized_reason}_to_reclaimable",
                step_index=effective_step_index,
            )
            if post_final_shared_one_shot_allowed:
                contract["post_final_shared_delayed_reclaim_used"] = True
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_RECLAIMABLE
        contract["runtime_claim_rearm_reason"] = normalized_reason
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 1
        self._record_protected_hedge_runtime_claim_rearm(
            contract=contract,
            reason=normalized_reason,
            step_index=effective_step_index,
        )
        self.last_protected_hedge_contract = contract
        self._reassert_protected_hedge_visibility_hysteresis(
            contract=contract,
            step_index=effective_step_index,
        )
        return True

    def _make_protected_hedge_runtime_claim_final_reclaimable(
        self,
        *,
        reason: str,
        step_index: int | None = None,
    ) -> bool:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract or not self._protected_hedge_contract_active(contract):
            return False
        if bool(contract.get("runtime_final_reclaim_used", False)):
            return False
        current_claim_state = self._protected_hedge_runtime_claim_state(contract)
        if current_claim_state != self.PROTECTED_HEDGE_CLAIM_STATE_POST_RECLAIM_HOLD:
            return False
        if not self._post_reclaim_hold_ready_for_final_reclaim(contract):
            return False
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        ready_source = self._post_reclaim_hold_ready_source(contract)
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_FINAL_RECLAIMABLE
        contract["runtime_claim_rearm_reason"] = str(reason or "")
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 1
        contract["final_reclaimable_entered_step_idx"] = effective_step_index
        contract["final_reclaimable_reason"] = str(reason or "")
        self._record_protected_hedge_runtime_claim_rearm(
            contract=contract,
            reason=str(reason or ""),
            step_index=effective_step_index,
        )
        self.last_protected_hedge_contract = contract
        self.last_protected_hedge_visible = True
        self.post_reclaim_stable_fail_count += 1
        self.final_reclaimable_count += 1
        self.post_reclaim_hold_guard_phase_entry_count += 1
        if ready_source:
            self.post_reclaim_hold_ready_source_histogram[ready_source] = int(
                self.post_reclaim_hold_ready_source_histogram.get(ready_source, 0) or 0
            ) + 1
            self.last_post_reclaim_hold_ready_source = ready_source
            if ready_source == "reclaim_ticket":
                self._consume_reclaim_ticket(
                    reason="final_reclaimable",
                    step_index=effective_step_index,
                )
        else:
            self.last_post_reclaim_hold_ready_source = ""
        exit_reason = (
            "runtime_confirm_to_final_reclaimable"
            if ready_source == "runtime_confirm"
            else "stable_fail_to_final_reclaimable"
        )
        self._record_post_reclaim_hold_exit_reason(exit_reason)
        return True

    def _exhaust_protected_hedge_runtime_claim(
        self,
        *,
        reason: str,
        step_index: int | None = None,
        reclaim_used: bool = False,
    ) -> None:
        contract = dict(self.last_protected_hedge_contract or {})
        if not contract:
            return
        effective_step_index = int(
            step_index if step_index is not None else (self.last_state.step_index if self.last_state else -1)
        )
        if self._post_final_shared_active(contract):
            self._exit_post_final_shared_tail(
                contract=contract,
                reason=f"shared_{str(reason or '').strip()}_to_exhausted",
                step_index=effective_step_index,
            )
        if str(reason or "") != "final_reclaim_complete":
            self._mark_final_reclaim_same_turn_collapse(
                contract=contract,
                step_index=effective_step_index,
            )
        self._record_successful_reclaim_exhaustion(
            contract=contract,
            step_index=effective_step_index,
        )
        contract["runtime_claim_state"] = self.PROTECTED_HEDGE_CLAIM_STATE_EXHAUSTED
        contract["runtime_claim_exhausted_reason"] = str(reason or "")
        contract["runtime_claim_last_transition_step_idx"] = effective_step_index
        contract["runtime_probe_budget"] = 0
        if reclaim_used:
            contract["runtime_reclaim_used"] = True
        self.last_protected_hedge_contract = contract

    def _protected_hedge_runtime_probe_budget(self, contract: dict[str, Any] | None = None) -> int:
        item = contract if contract is not None else self.last_protected_hedge_contract or {}
        if not item or not self._protected_hedge_contract_active(item):
            return 0
        if self._protected_hedge_runtime_probe_pending(item):
            return 1
        return 0

