        structural_time_shadow_ready = bool(structural_time_summary)
        structural_time_hot_regions: list[dict[str, Any]] = []
        raw_structural_time_hot_regions = structural_time_summary.get("affordance_hot_regions", []) or []
        if isinstance(raw_structural_time_hot_regions, list):
            for raw_hot_region in raw_structural_time_hot_regions[:5]:
                if not isinstance(raw_hot_region, dict):
                    continue
                structural_time_hot_regions.append(
                    {
                        str(key): value
                        for key, value in raw_hot_region.items()
                        if isinstance(value, (str, int, float, bool)) or value is None
                    }
                )
        structural_time_top_hot_region = (
            structural_time_hot_regions[0] if structural_time_hot_regions else {}
        )
