        selected_family_effect = self._local_effect_family_entry_for(family=selected_target_family)
        active_transition_frontier = self._active_local_transition_frontier_entries(
            current_step=state.step_index
        )
        top_transition_frontier = active_transition_frontier[0] if active_transition_frontier else {}
        executed_action_payload_raw = getattr(self, "last_executed_action_payload", {}) or {}
        executed_action_payload: dict[str, Any] = {}
        if isinstance(executed_action_payload_raw, dict):
            for key, value in executed_action_payload_raw.items():
                if isinstance(value, (str, int, float, bool)) or value is None:
                    executed_action_payload[str(key)] = value
                else:
                    executed_action_payload[str(key)] = str(value)
