            if queue_exhaustion_recovery_source != self.PRESERVED_ALTERNATIVE_KIND_NONE:
                queue_exhaustion_recovery_source_histogram[queue_exhaustion_recovery_source] = int(
                    queue_exhaustion_recovery_source_histogram.get(queue_exhaustion_recovery_source, 0) or 0
                ) + 1
